# ---------------- Tokenizer -----------------
_MULTI_OPS = ["<<=", ">>=", "->*", "...", "++", "--", "->", "::", "<<", ">>", "<=", ">=",
              "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=",
              ".*", "##"]
def _decode_string(raw):
    # raw includes quotes
    body = raw[1:-1] if len(raw) >= 2 else ""
    out = []
    i = 0
    while i < len(body):
        c = body[i]
        if c == "\\" and i + 1 < len(body):
            n = body[i+1]
            mp = {"n":"\n","t":"\t","r":"\r","0":"\0","\\":"\\",'"':'"',"'":"'", "a":"\a","b":"\b","f":"\f","v":"\v"}
            if n in mp:
                out.append(mp[n]); i += 2; continue
            if n == "x":
                j = i+2; hx = ""
                while j < len(body) and body[j] in "0123456789abcdefABCDEF":
                    hx += body[j]; j += 1
                if hx:
                    try: out.append(chr(int(hx, 16)))
                    except Exception: pass
                    i = j; continue
            out.append(n); i += 2; continue
        out.append(c); i += 1
    return "".join(out)

def _parse_number(text):
    t = text
    try:
        tt = t.rstrip("uUlLfF")
        if tt.lower().startswith("0x"):
            return int(tt, 16)
        if tt.lower().startswith("0b"):
            return int(tt, 2)
        if len(tt) > 1 and tt[0] == "0" and all(c in "01234567" for c in tt):
            return int(tt, 8)
        if "." in tt or "e" in tt.lower():
            return float(tt)
        return int(tt)
    except Exception:
        return None

def tokenize_text(display, path, lines):
    """lines: list of (line_no, text). Returns list[Token] with comments removed."""
    toks = []
    # Build joined text with line start offsets
    line_starts = []
    parts = []
    offset = 0
    line_text_by_no = {}
    for (ln, txt) in lines:
        line_starts.append((offset, ln, txt))
        line_text_by_no[ln] = txt
        parts.append(txt)
        offset += len(txt) + 1
    text = "\n".join(parts)
    def locate(pos):
        # binary search
        lo, hi = 0, len(line_starts)-1
        ans = 0
        while lo <= hi:
            mid = (lo+hi)//2
            if line_starts[mid][0] <= pos:
                ans = mid; lo = mid + 1
            else:
                hi = mid - 1
        start, ln, txt = line_starts[ans]
        return ln, pos - start + 1, txt
    i = 0; n = len(text)
    while i < n:
        c = text[i]
        if c in " \t\r\n":
            i += 1; continue
        if text.startswith("//", i):
            j = text.find("\n", i)
            i = n if j < 0 else j
            continue
        if text.startswith("/*", i):
            j = text.find("*/", i+2)
            i = n if j < 0 else j+2
            continue
        ln, col, ltxt = locate(i)
        # string / char with optional prefixes
        start = i
        prefix = ""
        if c in "uUL" and i+1 < n and text[i+1] in "\"'":
            prefix = c; i += 1; c = text[i]
        elif text.startswith('u8"', i) or text.startswith('u8\'', i):
            prefix = "u8"; i += 2; c = text[i]
        if c == '"' or c == "'":
            quote = c; i += 1
            while i < n:
                if text[i] == "\\":
                    i += 2; continue
                if text[i] == quote:
                    i += 1; break
                if text[i] == "\n":
                    break
                i += 1
            raw = text[start:i]
            kind = "str" if quote == '"' else "char"
            val = _decode_string(raw) if kind == "str" else (_decode_string(raw) if len(raw) > 1 else "")
            toks.append(Token(raw, display, path, ln, col, ltxt, kind, val))
            continue
        if c.isalpha() or c == "_" or c == "$":
            j = i+1
            while j < n and (text[j].isalnum() or text[j] in "_$"):
                j += 1
            word = text[i:j]
            toks.append(Token(word, display, path, ln, col, ltxt, "id", None))
            i = j; continue
        if c.isdigit() or (c == "." and i+1 < n and text[i+1].isdigit()):
            j = i
            while j < n and (text[j].isalnum() or text[j] in "._'"):
                j += 1
            raw = text[i:j]
            toks.append(Token(raw, display, path, ln, col, ltxt, "num", _parse_number(raw)))
            i = j; continue
        matched = None
        for op in _MULTI_OPS:
            if text.startswith(op, i):
                matched = op; break
        if matched:
            toks.append(Token(matched, display, path, ln, col, ltxt, "op", None))
            i += len(matched); continue
        toks.append(Token(c, display, path, ln, col, ltxt, "op", None))
        i += 1
    return toks

def tokens_text(toks):
    return " ".join(t.text for t in toks)
def tokens_compact(toks):
    return "".join(t.text for t in toks)

# ---------------- Expression evaluation (constant folding) -----------------
class Eval:
    """Evaluate token range to (value, type_name) where value may be int/float/bool/str/None."""
    def __init__(self, toks, var_values=None):
        self.toks = toks
        self.pos = 0
        self.var_values = var_values or {}  # name -> (value, type)
    def peek(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else None
    def next(self):
        t = self.peek(); self.pos += 1; return t
    def parse(self):
        if not self.toks:
            return None
        v = self.parse_ternary()
        return v
    def parse_ternary(self):
        v = self.parse_or()
        t = self.peek()
        if t and t.text == "?":
            self.next()
            a = self.parse_ternary()
            if self.peek() and self.peek().text == ":":
                self.next()
            b = self.parse_ternary()
            if isinstance(v, (int, float, bool)):
                return a if v else b
            return None
        return v
    def _bin(self, sub, ops):
        v = sub()
        while True:
            t = self.peek()
            if not t or t.text not in ops:
                return v
            op = self.next().text
            r = sub()
            v = self._apply(op, v, r)
    def parse_or(self):  return self._bin(self.parse_and, {"||"})
    def parse_and(self): return self._bin(self.parse_bitor, {"&&"})
    def parse_bitor(self): return self._bin(self.parse_bitxor, {"|"})
    def parse_bitxor(self): return self._bin(self.parse_bitand, {"^"})
    def parse_bitand(self): return self._bin(self.parse_eq, {"&"})
    def parse_eq(self): return self._bin(self.parse_rel, {"==", "!="})
    def parse_rel(self): return self._bin(self.parse_shift, {"<", "<=", ">", ">="})
    def parse_shift(self): return self._bin(self.parse_add, {"<<", ">>"})
    def parse_add(self): return self._bin(self.parse_mul, {"+", "-"})
    def parse_mul(self): return self._bin(self.parse_unary, {"*", "/", "%"})
    def _apply(self, op, a, b):
        if a is None or b is None:
            # special: boolean ops with None unknown
            return None
