            self.next(); return self.parse_unary()
        return self.parse_postfix()
    def parse_postfix(self):
        v = self.parse_primary()
        while True:
            t = self.peek()
            if t and t.text in ("++", "--"):
                self.next(); continue
            if t and t.text == "(":
                # function call - unknown value
                self._skip_balanced("(", ")")
                v = None; continue
            if t and t.text == "[":
                self._skip_balanced("[", "]")
                # array element value unknown unless handled by caller
                v = None; continue
            if t and t.text in (".", "->"):
                self.next()
                if self.peek(): self.next()
                v = None; continue
            break
