        t = self.next()
        if t is None: return None
        if t.kind == "num":
            return t.value
        if t.kind == "char":
            v = t.value
            if isinstance(v, str) and len(v) >= 1:
                return ord(v[0])
            return None
        if t.kind == "str":
            return t.value
        if t.text == "(":
            v = self.parse_ternary()
            if self.peek() and self.peek().text == ")":
                self.next()
            return v
        if t.text in ("true",): return True
        if t.text in ("false",): return False
        if t.text in ("NULL", "nullptr"): return 0
        if t.text == "sizeof":
            # sizeof(type/var) approximate
            if self.peek() and self.peek().text == "(":
                self._skip_balanced("(", ")")
            return None
        if t.kind == "id" or t.text in TYPE_KEYWORDS:
            # cast-like or identifier; may be followed by :: etc.
            name = t.text
            while self.peek() and self.peek().text == "::":
                self.next()
                nt = self.next()
                if nt: name = nt.text
            if name in self.var_values:
                return self.var_values[name][0]
            return None
        return None

def evaluate_tokens(toks, var_values=None):
    if not toks:
        return None
    try:
        return Eval(list(toks), var_values).parse()
    except Exception:
        return None

