        if self.language == "cpp":
            defined.update(["__cplusplus", "__STDC__", "__STDC_HOSTED__"])
            macros["__cplusplus"] = Macro(None, ["201703L"])
        else:
            defined.update(["__STDC__", "__STDC_HOSTED__", "__STDC_VERSION__"])
        plat = self.settings.platform
        if plat.startswith("win"):
            defined.update(["_WIN32", "WIN32"])
            macros["_WIN32"] = Macro(None, ["1"])
            if plat == "win64":
                defined.add("_WIN64"); macros["_WIN64"] = Macro(None, ["1"])
        else:
            defined.update(["__linux__", "__unix__", "unix", "__GNUC__"])
