    def initial_macros(self):
        macros = {}
        defined = set()
        if self.language == "cpp":
            defined.update(["__cplusplus", "__STDC__", "__STDC_HOSTED__"])
            macros["__cplusplus"] = Macro(None, ["201703L"])
        else:
            defined.update(["__STDC__", "__STDC_HOSTED__", "__STDC_VERSION__"])
        plat = self.settings.platform
        if plat.startswith("win"):
            defined.update(["_WIN32", "WIN32"])
            macros["_WIN32"] = Macro(None, ["1"])
            if plat == "win64":
                defined.add("_WIN64"); macros["_WIN64"] = Macro(None, ["1"])
        else:
            defined.update(["__linux__", "__unix__", "unix", "__GNUC__"])
        # user defines
        all_defs = list(self.settings.defines) + list(self.extra_defines)
        for (name, value) in all_defs:
            if not name: continue
            toks = tokenize_text("", "", [(1, value)]) if value else []
            macros[name] = Macro(None, [t.text for t in toks] if toks else ["1"])
            defined.add(name)
        for u in self.settings.undefines:
            macros.pop(u, None)
            defined.discard(u)
        return macros, defined

    def find_include(self, spec, is_system, cur_display, cur_path):
        name = spec
        dirs = []
        if not is_system:
            d = os.path.dirname(cur_path)
            dd = os.path.dirname(cur_display)
            dirs.append((d, dd))
        for inc in list(self.extra_includes) + list(self.settings.include_paths):
            dirs.append((inc, inc))
        # forced includes search not relevant
        for (actual_dir, disp_dir) in dirs:
            actual = os.path.join(actual_dir, name) if actual_dir else name
            if os.path.isfile(actual):
                disp = os.path.join(disp_dir, name) if disp_dir else name
                disp = disp.replace("./", "", 1) if disp.startswith("./") else disp
                return actual, disp
        return None, None

    def process(self):
        macros, defined = self.initial_macros()
        fi = self.main_fi
        text = read_source(fi.path)
        lines_raw = text.splitlines()
        register_lines(fi.display, lines_raw)
        self._process_file(fi.display, fi.path, lines_raw, macros, defined, is_main=True)
        return self.result

    def _process_file(self, display, path, lines_raw, macros, defined, is_main=False):
        cleaned = clean_source("\n".join(lines_raw)).splitlines()
        # ensure length
        while len(cleaned) < len(lines_raw):
            cleaned.append("")
        stack = []  # frames dict
        def is_active():
            return all(f["active"] for f in stack)
        for idx, raw_line in enumerate(lines_raw):
            ln = idx + 1
            cline = cleaned[idx] if idx < len(cleaned) else ""
            stripped = cline.lstrip()
            if stripped.startswith("#"):
