def clean_source(text):
    """Blank comments preserving layout; keep strings."""
    out = []
    i = 0; n = len(text)
    state = "code"
    while i < n:
        c = text[i]
        if state == "code":
            if text.startswith("//", i):
                out.append("  "); i += 2; state = "linecomment"; continue
            if text.startswith("/*", i):
                out.append("  "); i += 2; state = "blockcomment"; continue
            if c == '"':
                out.append(c); i += 1; state = "string"; continue
            if c == "'":
                out.append(c); i += 1; state = "char"; continue
            # line splice
            if c == "\\" and i+1 < n and text[i+1] == "\n":
                out.append("  "); i += 2; continue
            out.append(c); i += 1; continue
        if state == "linecomment":
            if c == "\n":
                out.append(c); state = "code"
            else:
                out.append(" ")
            i += 1; continue
        if state == "blockcomment":
            if text.startswith("*/", i):
                out.append("  "); i += 2; state = "code"; continue
            out.append("\n" if c == "\n" else " "); i += 1; continue
        if state in ("string", "char"):
            quote = '"' if state == "string" else "'"
            out.append(c)
            if c == "\\" and i+1 < n:
                out.append(text[i+1]); i += 2; continue
            if c == quote or c == "\n":
