            cline = cleaned[idx] if idx < len(cleaned) else ""
            stripped = cline.lstrip()
            if stripped.startswith("#"):
                # directive
                rest = stripped[1:].lstrip()
                m = re.match(r"([A-Za-z_]\w*)", rest)
                word = m.group(1) if m else ""
                word_col = (len(cline) - len(stripped)) + 2  # '#' +1 adjusted below if spaces
                # column of word: position in original line
                wm = re.search(r"#\s*" + re.escape(word), cline) if word else None
                word_col = (wm.start() + len(wm.group(0)) - len(word) + 1) if wm else 2
                after = rest[len(word):].strip() if word else ""
                active_before = is_active()
                # conditional directives always
                if word in ("ifdef", "ifndef"):
                    if not after or not re.match(r"[A-Za-z_]\w*", after):
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag("syntaxError", f"Syntax error in #{word}", loc, critical=True, file0=False))
                        self.result.has_critical = True
                        stack.append({"active": False, "taken": True, "parent": active_before})
                    else:
                        name = re.match(r"[A-Za-z_]\w*", after).group(0)
                        cond = (name in macros or name in defined)
                        if word == "ifndef": cond = not cond
                        stack.append({"active": active_before and cond, "taken": cond, "parent": active_before})
                    if is_main: self.result.e_lines.append("")
                    continue
                if word == "if":
                    if not after:
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag("syntaxError", "Syntax error in #if", loc, critical=True, file0=False))
                        self.result.has_critical = True
                        stack.append({"active": False, "taken": True, "parent": active_before})
                    else:
                        cond = eval_pp_expr(after, macros, defined)
                        if cond is None: cond = False
                        stack.append({"active": active_before and cond, "taken": cond, "parent": active_before})
                    if is_main: self.result.e_lines.append("")
                    continue
                if word == "elif":
                    if not stack:
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag("syntaxError", "#elif without #if", loc, critical=True, file0=False))
                        self.result.has_critical = True
                    else:
                        f = stack[-1]
                        if f.get("taken"):
                            f["active"] = False
                        else:
                            cond = eval_pp_expr(after, macros, defined) if after else False
                            f["active"] = f["parent"] and bool(cond)
                            if cond: f["taken"] = True
                    if is_main: self.result.e_lines.append("")
                    continue
                if word == "else":
                    if not stack:
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag("syntaxError", "#else without #if", loc, critical=True, file0=False))
                        self.result.has_critical = True
                    else:
                        f = stack[-1]
                        f["active"] = f["parent"] and not f.get("taken")
                        f["taken"] = True
                    if is_main: self.result.e_lines.append("")
                    continue
                if word == "endif":
                    if not stack:
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag("syntaxError", "#endif without #if", loc, critical=True, file0=False))
                        self.result.has_critical = True
                    else:
                        stack.pop()
                    if is_main: self.result.e_lines.append("")
                    continue
                if not active_before:
                    if is_main: self.result.e_lines.append("")
                    continue
                # non-conditional, active only
                if word == "define":
                    if not after:
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag("syntaxError", "Failed to parse #define", loc, critical=True, file0=False))
                        self.result.has_critical = True
                    else:
                        dm = re.match(r"([A-Za-z_]\w*)", after)
                        if not dm:
                            loc = Loc(display, ln, word_col)
                            self.result.diags.append(make_diag("syntaxError", "Failed to parse #define", loc, critical=True, file0=False))
                            self.result.has_critical = True
                        else:
                            name = dm.group(1)
                            remainder = after[dm.end():]
                            params = None
                            if remainder.startswith("("):
                                close = remainder.find(")")
                                if close >= 0:
                                    plist = remainder[1:close].strip()
                                    params = [p.strip() for p in plist.split(",") if p.strip() and p.strip() != "..."] if plist else []
                                    remainder = remainder[close+1:]
                            repl_toks = tokenize_text(display, path, [(ln, remainder.strip())])
                            macros[name] = Macro(params, [t.text for t in repl_toks])
                            defined.add(name)
                    if is_main: self.result.e_lines.append("")
                    continue
                if word == "undef":
                    nm = re.match(r"[A-Za-z_]\w*", after)
                    if nm:
                        macros.pop(nm.group(0), None); defined.discard(nm.group(0))
                    if is_main: self.result.e_lines.append("")
                    continue
                if word == "include":
                    inc_toks = tokenize_text(display, path, [(ln, cline)])
                    # find spec
                    spec = None; is_system = False
                    mm = re.search(r"<([^>]+)>", cline)
                    mq = re.search(r'"([^"]+)"', cline)
                    if mq:
                        spec = mq.group(1); is_system = False
                    elif mm:
                        spec = mm.group(1); is_system = True
                    if spec is None:
                        if is_main: self.result.e_lines.append("")
                        continue
                    actual, disp = self.find_include(spec, is_system, display, path)
                    if actual is None:
                        if is_system:
                            msg = f"Include file: <{spec}> not found. Please note: Standard library headers do not need to be provided to get proper results."
                            eid = "missingIncludeSystem"
                        else:
                            msg = f'Include file: "{spec}" not found.'
                            eid = "missingInclude"
                        loc = Loc(display, ln, word_col)
                        self.result.diags.append(make_diag(eid, msg, loc, gate="missingInclude", file0=False))
                        if is_main: self.result.e_lines.append("")
                    else:
                        if self.include_depth > 20:
                            if is_main: self.result.e_lines.append("")
                            continue
                        htext = read_source(actual)
                        hlines = htext.splitlines()
                        register_lines(disp, hlines)
                        if is_main:
                            self.result.e_lines.append("")
                            self.result.e_lines.append(f'#line 2 "{disp}"')
                        self.include_depth += 1
                        sub_start = len(self.result.e_lines)
                        self._process_file(disp, actual, hlines, macros, defined, is_main=False)
                        self.include_depth -= 1
                        if is_main:
                            # included e-lines are not tracked for headers; add marker back
                            self.result.e_lines.append(f'#line {ln+1} "{display}"')
                    continue
                if word == "error":
                    loc = Loc(display, ln, word_col)
                    msg = "#error " + after if after else "#error "
                    self.result.diags.append(make_diag("preprocessorErrorDirective", msg, loc, critical=True, file0=False))
                    self.result.has_critical = True
                    if is_main: self.result.e_lines.append("")
                    continue
                # warning/pragma/unknown/empty directive: nothing
                if is_main: self.result.e_lines.append("")
                continue
            else:
                if not is_active():
                    if is_main: self.result.e_lines.append("")
                    continue
                toks = tokenize_text(display, path, [(ln, cline)])
                if toks:
                    toks = expand_tokens(toks, macros)
                    self.result.tokens.extend(toks)
                if is_main:
                    # -E rendering line
                    if toks:
                        s = ""
                        for ti, t in enumerate(toks):
                            if ti == 0:
                                s += t.text
                            else:
                                s += ("  " if t.from_macro else " ") + t.text
                        self.result.e_lines.append(s)
                    else:
                        self.result.e_lines.append("")
        # unmatched conditional at EOF is ignored by original in most cases

def discover_config_symbols(display, path, settings, language):
    text = read_source(path)
    cleaned = clean_source(text)
    symbols = []
    defined_in_file = set()
    for line in cleaned.splitlines():
        m = re.match(r"\s*#\s*define\s+([A-Za-z_]\w*)", line)
        if m: defined_in_file.add(m.group(1))
    user_defs = {n for (n, v) in settings.defines}
    for line in cleaned.splitlines():
        for pat in (r"\s*#\s*ifdef\s+([A-Za-z_]\w*)", r"\s*#\s*ifndef\s+([A-Za-z_]\w*)", r"defined\s*\(?\s*([A-Za-z_]\w*)"):
            m = re.search(pat, line) if "defined" not in pat else None
            # handle first two separately
            break
        m1 = re.match(r"\s*#\s*(?:ifdef|ifndef)\s+([A-Za-z_]\w*)", line)
        cand = []
        if m1: cand.append(m1.group(1))
        if re.match(r"\s*#\s*(?:if|elif)\b", line):
            for mm in re.finditer(r"defined\s*\(?\s*([A-Za-z_]\w*)", line):
                cand.append(mm.group(1))
        for name in cand:
            if name in defined_in_file or name in user_defs or name in settings.undefines:
                continue
            if name in ("__cplusplus", "__STDC__", "__STDC_VERSION__", "__STDC_HOSTED__"):
                continue
            if name not in symbols:
                symbols.append(name)
    return symbols

