        cands = []
        if function is not None:
            for v in self.local_vars:
                if v.name == name and v.function is function and v.decl_index <= idx and v.scope_start <= idx <= v.scope_end:
                    cands.append(v)
            if cands:
                return max(cands, key=lambda v: v.decl_index)
        for v in self.global_vars:
            if v.name == name: return v
        if function is not None and function.class_name:
            for ci in self.classes:
                if ci.name == function.class_name:
                    for m in ci.members:
                        if m.name == name:
                            # pseudo member var (shared object from class)
                            return m
        # global from other? search local vars of other functions not visible
        return None

    def collect_calls(self):
        def_names = {f.name_index for f in self.functions}
        for i, t in enumerate(self.toks):
            if t.kind == "id" and t.text not in KEYWORDS:
                if i in def_names: continue
                if i+1 < len(self.toks) and self.toks[i+1].text == "(":
                    if i > 0 and self.toks[i-1].text in (".", "->", "::"):
                        self.member_called.add(t.text)
                    else:
                        self.called_names.add(t.text)
                else:
                    # address / reference to function name counts as use
                    if any(f.name == t.text for f in self.functions):
                        if not (i > 0 and self.toks[i-1].text in (".","->")):
                            # don't count its own declaration tokens (in ret type etc) - decl name handled
                            self.called_names.add(t.text)

