    # ---------- sequential analysis ----------
    def token_index_map(self):
        return {id(t): i for i, t in enumerate(self.toks)}

    def run(self):
        if self.critical:
            return self.diags
        self.syntax_checks()
        if self.critical:
            return [d for d in self.diags if d.critical]
        self.index_map = self.token_index_map()
        self.discover_classes()
        self.discover_functions()
        self.collect_prototypes()
        self.discover_variables()
        self.collect_calls()
        self.conditional_source = {}
        self._mark_conditionals()
        self.active_loop_ranges = []  # list dict
        self.loop_header_ranges = []
        self.extra_assignments = {}   # (kind,id,expr) -> dict
        self.global_skip = {}
        # build global skip ranges
        for f in self.functions:
            self.global_skip[f.body_start] = f.body_end
        for ci in self.classes:
            self.global_skip[ci.start] = ci.end
        # global processing first
        self.cur_function = None
        self.cur_states = {}
        self.process_range(0, len(self.toks))
        self.global_known = {id(s.var): s.known for s in self.cur_states.values() if s.known is not None}
        # functions
        for f in self.functions:
            self.process_function(f)
        self.generic_scans()
        # branch limiting
        if self.known_if_count >= 5 and self.settings.check_level == "normal":
            d = make_diag("normalCheckLevelMaxBranches",
                          "Limiting analysis of branches. Use --check-level=exhaustive to analyze all branches.",
                          Loc(self.fi.display, 0, 0), gate="information", file0=False)
            self.diags.append(d)
        # unused struct members
        self.check_unused_struct_members()
        self.check_no_constructors()
        return self.diags

    def _mark_conditionals(self):
        n = len(self.toks)
        for i, t in enumerate(self.toks):
            if t.text in ("if", "while"):
                if i+1 < n and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
                    pc = self.match_paren[i+1]
                    body_start = pc + 1
                    if body_start < n:
                        body_end = self.statement_range(body_start)
                        cond_tok = self.toks[i+2] if i+2 < pc else self.toks[i+1]
                        for k in range(body_start, min(body_end, n)):
                            self.conditional_source[k] = cond_tok
            elif t.text == "else":
                body_start = i + 1
                if body_start < n and self.toks[body_start].text != "if":
                    body_end = self.statement_range(body_start)
                    # find preceding if condition token (approx: use else token)
                    for k in range(body_start, min(body_end, n)):
                        if k not in self.conditional_source:
                            self.conditional_source[k] = t
            elif t.text == "for":
                if i+1 < n and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
                    pc = self.match_paren[i+1]
                    body_start = pc + 1
                    if body_start < n:
                        body_end = self.statement_range(body_start)
                        cond_tok = self.toks[i+2] if i+2 < pc else t
                        for k in range(body_start, min(body_end, n)):
                            self.conditional_source[k] = cond_tok

    def statement_range(self, start):
        n = len(self.toks)
        if start >= n: return start
        t = self.toks[start]
        if t.text == "{" and start in self.match_brace:
            return self.match_brace[start] + 1
        if t.text == "if":
            if start+1 < n and self.toks[start+1].text == "(" and (start+1) in self.match_paren:
                pc = self.match_paren[start+1]
                e = self.statement_range(pc+1)
                if e < n and self.toks[e].text == "else":
                    return self.statement_range(e+1)
                return e
            return start + 1
        if t.text in ("for", "while", "switch"):
            if start+1 < n and self.toks[start+1].text == "(" and (start+1) in self.match_paren:
                pc = self.match_paren[start+1]
                return self.statement_range(pc+1)
            return start + 1
        if t.text == "do":
            e = self.statement_range(start+1)
            # while (...);
            if e < n and self.toks[e].text == "while":
                if e+1 < n and self.toks[e+1].text == "(" and (e+1) in self.match_paren:
                    pc = self.match_paren[e+1]
                    if pc+1 < n and self.toks[pc+1].text == ";": return pc+2
                    return pc+1
            return e
        # simple statement to semicolon
        i = start
        while i < n:
            tx = self.toks[i].text
            if tx == "{" and i in self.match_brace:
                i = self.match_brace[i] + 1; continue
            if tx == ";":
                return i + 1
            if tx == "}":
                return i
            i += 1
        return n

    def get_state(self, var):
        key = id(var)
        if key not in self.cur_states:
            st = VarState(var)
            if var.is_global and id(var) in getattr(self, "global_known", {}):
                st.known = self.global_known[id(var)]
            self.cur_states[key] = st
        return self.cur_states[key]

    def var_values_snapshot(self):
        out = {}
        for st in self.cur_states.values():
            if st.known is not None:
                out[st.var.name] = (st.known, st.var.type_text())
        # globals known from declarations even if not touched
        return out

    def eval_range(self, s, e):
        if s >= e: return None
        return evaluate_tokens(self.toks[s:e], self.var_values_snapshot())

    def is_in_condition(self, idx):
        # find enclosing '('
        # walk backwards with depth
        depth = 0
        i = idx - 1
        while i >= 0:
            tx = self.toks[i].text
            if tx == ")": depth += 1
            elif tx == "(":
                if depth == 0:
                    if i > 0 and self.toks[i-1].text in ("if", "while"):
                        return True
                    if i > 0 and self.toks[i-1].text == "for":
                        # only condition segment: between first and second ';'
                        pc = self.match_paren.get(i)
                        if pc:
                            semis = [k for k in range(i+1, pc) if self.toks[k].text == ";"]
                            if len(semis) >= 2:
                                return semis[0] < idx < semis[1]
                            elif len(semis) == 1:
                                return idx < semis[0]  # range-for / init? treat no
                        return False
                    return False
                depth -= 1
            elif tx in (";", "{", "}") and depth == 0:
                return False
            i -= 1
        return False

    def find_expr_end(self, start, limit):
        depth_p = depth_b = 0; tern = 0; i = start
        while i < limit:
            tx = self.toks[i].text
            if tx == "(" : depth_p += 1
            elif tx == ")":
                if depth_p == 0: break
                depth_p -= 1
            elif tx == "[": depth_b += 1
            elif tx == "]":
                if depth_b == 0: break
                depth_b -= 1
            elif tx == "{" and i in self.match_brace:
                i = self.match_brace[i] + 1; continue
            elif tx == "}" and depth_p == 0 and depth_b == 0:
                break
            elif depth_p == 0 and depth_b == 0:
                if tx in (";", ","): break
                if tx == "?": tern += 1
                elif tx == ":":
                    if tern > 0: tern -= 1
                    else: break
            i += 1
        return i

    def primary_before(self, op_idx):
        end = op_idx; i = op_idx - 1
        if i < 0: return (op_idx, op_idx)
        t = self.toks[i]
        if t.text in (")", "]"):
            mp = self.match_paren if t.text == ")" else self.match_bracket
            if i in mp:
                s = mp[i]
                # function call: include callee name
                if s > 0 and self.toks[s-1].kind == "id":
                    s -= 1
                    while s >= 2 and self.toks[s-1].text in (".", "->", "::"):
                        # include object primary roughly
                        s -= 2
                        # if object is parenthesized etc, stop
                        break
                return (s, end)
            return (i, end)
        if t.kind in ("id", "num", "str", "char") or t.text in ("true","false","nullptr","NULL"):
            s = i
            while s >= 2 and self.toks[s-1].text in (".", "->", "::"):
                # object/member chain
                if self.toks[s-2].kind in ("id","num") or self.toks[s-2].text in (")","]"):
                    s -= 2
                    if self.toks[s].text in (")","]"):
                        mp = self.match_paren if self.toks[s].text == ")" else self.match_bracket
                        if s in mp: s = mp[s]
                    continue
                break
            return (s, end)
        if t.text in ("++", "--"):
            return self.primary_before(i)
        return (i, end)

    def primary_after(self, op_idx, limit=None):
        limit = limit or len(self.toks)
        i = op_idx + 1
        # skip unary and casts
        while i < limit and self.toks[i].text in ("-", "+", "!", "~", "++", "--"):
            i += 1
        if i < limit and self.toks[i].text == "(":
            # cast if contents are type-like and followed by primary
            if i in self.match_paren:
                pc = self.match_paren[i]
                inside = self.toks[i+1:pc]
                if inside and all((x.kind == "id" or x.text in TYPE_KEYWORDS or x.text in ("*","&","&&","::","<",">",",","const","unsigned","signed","long","short")) for x in inside):
                    return self.primary_after(pc, limit)
                return (i, pc+1)
        if i >= limit: return (i, i)
        t = self.toks[i]
        if t.text == "(" and i in self.match_paren:
            return (i, self.match_paren[i] + 1)
        if t.kind in ("id","num","str","char") or t.text in ("true","false","nullptr","NULL"):
            e = i + 1
            while e < limit:
                if self.toks[e].text == "[" and e in self.match_bracket:
                    e = self.match_bracket[e] + 1; continue
                if self.toks[e].text == "(" and e in self.match_paren:
                    e = self.match_paren[e] + 1; continue
                if self.toks[e].text in (".", "->", "::") and e+1 < limit:
                    e += 2; continue
                if self.toks[e].text in ("++", "--"):
                    e += 1; continue
                break
            return (i, e)
        return (i, i+1)

