            if start+1 < n and self.toks[start+1].text == "(" and (start+1) in self.match_paren:
                pc = self.match_paren[start+1]
                e = self.statement_range(pc+1)
                if e < n and self.toks[e].text == "else":
                    return self.statement_range(e+1)
