    def process_function(self, f):
        self.cur_function = f
        self.cur_states = {}
        for p in f.params:
            self.get_state(p)
        # process body (including braces so scope finalisation happens)
        self.process_range(f.body_start, f.body_end + 1)
        # finalize remaining locals
        for v in list(self.local_vars):
            if v.function is f:
                st = self.get_state(v)
                if not st.finalized:
                    self.finalize_var(v, st)
        self.check_const_candidates(f)
        self.check_missing_return(f)
        self.cur_function = None

    def process_range(self, start, end):
        i = start
        while i < end:
            # pop expired loop ranges
            self.active_loop_ranges = [r for r in self.active_loop_ranges if not (r["body_end"] <= i)]
            t = self.toks[i]
            if self.cur_function is None and i in self.global_skip:
                i = self.global_skip[i] + 1; continue
            if i in self.decl_map:
                vs, stmt_end = self.decl_map[i]
                # only apply for matching context
                vfunc = vs[0].function if vs else None
                if vfunc is self.cur_function or (vfunc is None and self.cur_function is None and not (vs and vs[0].is_member)):
                    for v in vs:
                        st = self.get_state(v)
                        if v.init_tokens:
                            s_idx = self.index_map.get(id(v.init_tokens[0])) if v.init_tokens else None
                            e_idx = self.index_map.get(id(v.init_tokens[-1])) + 1 if v.init_tokens else None
                            if s_idx is not None and e_idx is not None:
                                # brace init: include braces? init_tokens exclude braces; fine
                                self.process_range(s_idx, e_idx)
                            self.finalize_assignment(v, v.init_token, v.init_tokens, "init", v.name, v.decl_token, is_init=True)
                    i = stmt_end + 1; continue
            if t.text == "sizeof":
                # skip sizeof expression (not evaluated)
                if i+1 < end and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
                    i = self.match_paren[i+1] + 1; continue
                # sizeof var
                s, e = self.primary_after(i, end); i = e; continue
            if t.text == "for" and i+1 < end and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
                i = self.handle_for(i, end); continue
            if t.text == "delete":
                j = i + 1
                if j < end and self.toks[j].text == "[" and j in self.match_bracket:
                    j = self.match_bracket[j] + 1
                    kind = "delete[]"
                else:
                    kind = "delete"
                if j < end and self.toks[j].kind == "id":
                    v = self.resolve_var(self.toks[j].text, j, self.cur_function)
                    if v is not None:
                        st = self.get_state(v); st.ever_used = True
                        self.handle_dealloc(v, t, self.toks[j], kind)
                        i = j + 1; continue
                i += 1; continue
            if t.text == "return":
                self.check_return(i, end)
                i += 1; continue
            if t.text == "catch":
                self.check_catch(i)
                i += 1; continue
            if t.kind == "id" and t.text not in KEYWORDS:
                ni = self.handle_identifier(i, end)
                if ni is not None:
                    i = ni; continue
                i += 1; continue
            if t.text in ("/","%","<<",">>","+","-","*","==","!=","<","<=",">",">="):
                self.handle_operator(i, end)
                i += 1; continue
            if t.text == "}":
                self.finalize_scope(i)
                i += 1; continue
            i += 1
        return i

    def handle_for(self, i, end):
        open_idx = i + 1; close_idx = self.match_paren[open_idx]
        # split header by ';'
        parts = []
        cur = open_idx + 1; dp = 0
