        for k in range(open_idx+1, close_idx):
            tx = self.toks[k].text
            if tx == "(": dp += 1
            elif tx == ")": dp -= 1
            elif tx == "[": db += 1
            elif tx == "]": db -= 1
            elif tx == "," and dp == 0 and db == 0:
