                at = self._arg_type(s, e)
                toks = self.toks[s:e]
                is_ptr = False
                if toks and toks[0].text == "&": is_ptr = True
                elif at and at.endswith("*"): is_ptr = True
                else:
                    # array name is pointer-like
                    if len(toks) == 1 and toks[0].kind == "id":
                        v = self.resolve_var(toks[0].text, s, self.cur_function)
                        if v is not None and (v.is_array or v.pointer): is_ptr = True
                if not is_ptr and at:
                    conv = sp["conv"]
                    if conv in "diouxX":
                        eid = "invalidScanfArgType_int"; exp = "int *"
                    elif conv in "fFeEgGaA":
                        eid = "invalidScanfArgType_float"; exp = "float *"
                    elif conv in "s":
                        eid = "invalidScanfArgType_s"; exp = "char *"
                    else: continue
                    loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                    msg = f"{sp['raw']} in format string (no. {idx+1}) requires '{exp}' but the argument type is '{at}'."
                    self.diags.append(make_diag(eid, msg, loc, severity="warning"))
            return
        # printf types
        # sprintf overlapping
        if name in ("sprintf","snprintf") and args:
            ds, de = args[0]
            dst_ids = [x.text for x in self.toks[ds:de] if x.kind == "id"]
            for (s, e) in value_args:
                ids = [x.text for x in self.toks[s:e] if x.kind == "id"]
                if dst_ids and any(x in dst_ids for x in ids):
                    loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                    msg = f"Undefined behavior: Variable '{dst_ids[0]}' is used as parameter and destination in s[n]printf()."
                    self.diags.append(make_diag("sprintfOverlappingData", msg, loc, symbol=dst_ids[0]))
                    break
        for idx, sp in enumerate(specs):
            if idx >= len(value_args): break
            s, e = value_args[idx]
            at = self._arg_type(s, e)
            if not at: continue
            conv = sp["conv"]
            checks = {
                "d": ("invalidPrintfArgType_sint", "int", {"int","char","short","bool"}),
                "i": ("invalidPrintfArgType_sint", "int", {"int","char","short","bool"}),
                "c": ("invalidPrintfArgType_sint", "int", {"int","char","short","bool"}),
                "u": ("invalidPrintfArgType_uint", "unsigned int", {"unsigned int"}),
                "x": ("invalidPrintfArgType_uint", "unsigned int", {"unsigned int"}),
                "X": ("invalidPrintfArgType_uint", "unsigned int", {"unsigned int"}),
                "o": ("invalidPrintfArgType_uint", "unsigned int", {"unsigned int"}),
                "s": ("invalidPrintfArgType_s", "char *", {"char *"}),
                "f": ("invalidPrintfArgType_float", "double", {"double","float"}),
                "e": ("invalidPrintfArgType_float", "double", {"double","float"}),
                "E": ("invalidPrintfArgType_float", "double", {"double","float"}),
                "g": ("invalidPrintfArgType_float", "double", {"double","float"}),
                "G": ("invalidPrintfArgType_float", "double", {"double","float"}),
                "a": ("invalidPrintfArgType_float", "double", {"double","float"}),
                "p": ("invalidPrintfArgType_p", "an address", None),  # special
                "n": ("invalidPrintfArgType_n", "int *", {"int *"}),
            }
            if conv not in checks: continue
            eid, exp, okset = checks[conv]
            if conv == "p":
                if at in ("int","char","short","bool","double","float"):
                    loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                    msg = f"{sp['raw']} in format string (no. {idx+1}) requires '{exp}' but the argument type is '{at}'."
                    self.diags.append(make_diag(eid, msg, loc, severity="warning"))
                continue
            if at not in okset:
                # allow long for %d? cppcheck promotes; skip long types
                if at in ("long",) and conv in "di": continue
                loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                msg = f"{sp['raw']} in format string (no. {idx+1}) requires '{exp}' but the argument type is '{at}'."
                self.diags.append(make_diag(eid, msg, loc, severity="warning"))

    def _dest_array(self, arg_range):
        s, e = arg_range
        toks = self.toks[s:e]
        if not toks: return None, None
        # &a[0] etc: first id
        for t in toks:
            if t.kind == "id":
                v = self.resolve_var(t.text, s, self.cur_function)
                if v is not None and v.is_array and v.array_size is not None:
                    elem = 4 if any(x.text in ("int","float") for x in v.type_tokens) else 1
                    if any(x.text in ("long","double") for x in v.type_tokens): elem = 8
                    if any(x.text == "short" for x in v.type_tokens): elem = 2
                    return v, v.array_size * elem
                if v is not None:
                    return v, None
        return None, None

    def _src_len(self, arg_range):
        s, e = arg_range
        toks = self.toks[s:e]
        if len(toks) == 1 and toks[0].kind == "str":
            return len(toks[0].value or "")
        v, sz = self._dest_array(arg_range)
        if v is not None and v.init_tokens and len(v.init_tokens) == 1 and v.init_tokens[0].kind == "str":
            return len(v.init_tokens[0].value or "")
        if v is not None:
            st = self.get_state(v)
            if st.string_token is not None:
                return len(st.string_token.value or "")
        return None

    def _check_buffer_call(self, name, fn_tok, args):
        if not args: return
        dst, dst_size = self._dest_array(args[0])
        if dst is None: return
        loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
        def report():
            msg = f"Buffer is accessed out of bounds: {dst.name}"
            self.diags.append(make_diag("bufferAccessOutOfBounds", msg, loc))
        if name == "strcpy" and len(args) >= 2 and dst_size is not None:
            sl = self._src_len(args[1])
            if sl is not None and sl + 1 > dst_size: report()
        elif name == "strcat" and len(args) >= 2 and dst_size is not None:
            sl = self._src_len(args[1])
            cur = self._src_len(args[0]) or 0
            if sl is not None and cur + sl + 1 > dst_size: report()
        elif name in ("memcpy","memmove","strncpy") and len(args) >= 3 and dst_size is not None:
            n = self.eval_range(args[2][0], args[2][1])
            if isinstance(n, int) and n > dst_size: report()
        elif name == "memset" and len(args) >= 3 and dst_size is not None:
            n = self.eval_range(args[2][0], args[2][1])
            if isinstance(n, int) and n > dst_size: report()

    # ---- operators ----
    def handle_operator(self, i, end):
        t = self.toks[i]; op = t.text
        in_loop_header = any(s <= i <= e for (s, e) in self.loop_header_ranges)
        if op in ("/", "%"):
            rs, re_ = self.primary_after(i, end)
            if rs < re_:
                val = self.eval_range(rs, re_)
                if isinstance(val, (int,float)) and val == 0:
                    loc = Loc(t.file, t.line, t.column)
                    callstack = []
                    # variable divisor with known assignment
                    if re_ - rs == 1 and self.toks[rs].kind == "id":
                        vv = self.resolve_var(self.toks[rs].text, rs, self.cur_function)
                        if vv is not None:
                            vst = self.get_state(vv)
                            if vst.known_token is not None:
                                kt = vst.known_token
                                callstack.append(Loc(kt.file, kt.line, kt.column, f"Assignment '{vv.name}={vst.known_rhs_text}', assigned value is 0"))
                    callstack.append(Loc(t.file, t.line, t.column, "Division by zero"))
                    d = make_diag("zerodiv", "Division by zero.", loc, info="Division by zero",
                                  callstack=callstack, has_notes=bool(len(callstack) > 1))
                    self.diags.append(d)
            return
        if op in ("<<", ">>"):
            rs, re_ = self.primary_after(i, end)
            ls, le = self.primary_before(i)
            amt = self.eval_range(rs, re_) if rs < re_ else None
            lval = self.eval_range(ls, le) if ls < le else None
            # determine LHS width / signed
            bits = 32; signed = True
            if ls < le:
                # literal suffix / value
                first = self.toks[ls]
                if first.kind == "id":
                    vv = self.resolve_var(first.text, ls, self.cur_function)
                    if vv is not None:
                        bits = vv.type_width(); signed = not vv.is_unsigned()
                    if first.text.endswith("_t"): bits = 32
                elif first.kind == "num":
                    raw = first.text.lower()
                    if "ll" in raw: bits = 64
                    elif "l" in raw: bits = 64
                    if "u" in raw: signed = False
                    if isinstance(first.value, int) and (first.value > 2**31 or first.value < -2**31): bits = 64
            if isinstance(amt, int):
                if amt < 0:
                    loc = Loc(t.file, t.line, t.column)
                    self.diags.append(make_diag("shiftNegative", "Shifting by a negative value is undefined behaviour", loc))
                elif amt >= bits:
                    loc = Loc(t.file, t.line, t.column)
                    self.diags.append(make_diag("shiftTooManyBits", f"Shifting {bits}-bit value by {amt} bits is undefined behaviour", loc))
                elif signed and amt == bits - 1 and isinstance(lval, int) and lval > 0:
                    loc = Loc(t.file, t.line, t.column)
                    self.diags.append(make_diag("shiftTooManyBitsSigned", f"Shifting signed {bits}-bit value by {amt} bits is undefined behaviour", loc))
                # integer overflow for <<
                if op == "<<" and signed and isinstance(lval, int) and isinstance(amt, int) and 0 <= amt < 128:
                    res = lval << amt
                    lo, hi = (-(1 << (bits-1)), (1 << (bits-1)) - 1)
                    if res > hi or res < lo:
                        loc = Loc(t.file, t.line, t.column)
                        ex = expr_text(self.toks[ls:le]) + op + expr_text(self.toks[rs:re_])
                        self.diags.append(make_diag("integerOverflow", f"Signed integer overflow for expression '{ex}'.", loc))
            return
        if op in ("+", "-", "*") and op != "*":
            # skip pointer deref/mult ambiguity for *: primary extraction may still work for numbers
            ls, le = self.primary_before(i); rs, re_ = self.primary_after(i, end)
            if ls < le and rs < re_:
                lv = self.eval_range(ls, le); rv = self.eval_range(rs, re_)
                if isinstance(lv, int) and isinstance(rv, int):
                    # unsigned operands skip
                    def is_unsigned_range(s, e):
                        toks = self.toks[s:e]
                        return any(x.text.lower().endswith("u") and x.kind == "num" for x in toks)
                    if not is_unsigned_range(ls, le) and not is_unsigned_range(rs, re_):
                        res = lv + rv if op == "+" else (lv - rv if op == "-" else lv * rv)
                        lo, hi = (-(1 << 31), (1 << 31) - 1)
                        if res > hi or res < lo:
                            loc = Loc(t.file, t.line, t.column)
                            ex = expr_text(self.toks[ls:le]) + op + expr_text(self.toks[rs:re_])
                            self.diags.append(make_diag("integerOverflow", f"Signed integer overflow for expression '{ex}'.", loc))
            return
        if op == "*":
            return
        if op in ("==","!=","<","<=",">",">="):
            if in_loop_header: return
            ls, le = self.primary_before(i); rs, re_ = self.primary_after(i, end)
            if ls >= le or rs >= re_: return
            # bool comparison special
            self._check_bool_compare(i, ls, le, rs, re_)
            lv = self.eval_range(ls, le); rv = self.eval_range(rs, re_)
            # variable type-range determination
            type_always = False
            # unsigned var < 0 etc
            for (s, e, other_val, is_left) in ((ls, le, rv, True), (rs, re_, lv, False)):
                toks = self.toks[s:e]
                if len(toks) == 1 and toks[0].kind == "id" and isinstance(other_val, int):
                    vv = self.resolve_var(toks[0].text, s, self.cur_function)
                    if vv is not None and vv.is_unsigned():
                        if is_left and ((op == "<" and other_val == 0) or (op == ">=" and other_val == 0)):
                            type_always = True
                        if not is_left and ((op == ">" and other_val == 0) or (op == "<=" and other_val == 0)):
                            type_always = True
            if lv is None or rv is None: return
            # at least one side must contain a variable id
            if not any(x.kind == "id" for x in self.toks[ls:le] + self.toks[rs:re_]): return
            try:
                res = {"==": lv==rv, "!=": lv!=rv, "<": lv<rv, "<=": lv<=rv, ">": lv>rv, ">=": lv>=rv}[op]
            except Exception:
                return
            # determine format variant
            equal_vals = (lv == rv)
            use_comparison = False
            if res and equal_vals and op in ("==","<=",">=","<",">"):
                # borderline equality cases as observed
                use_comparison = True
            if type_always:
                use_comparison = True
            left_txt_c = expr_text(self.toks[ls:le]); right_txt_c = expr_text(self.toks[rs:re_])
            if use_comparison:
                expr_sp = expr_text(self.toks[ls:le] + [t] + self.toks[rs:re_], spaced=True)
                msg = f"The comparison '{expr_sp}' is always {'true' if res else 'false'}."
                note_kind = "assigned"
            else:
                expr_c = left_txt_c + op + right_txt_c
                msg = f"Condition '{expr_c}' is always {'true' if res else 'false'}"
                note_kind = "assignment"
            first_tok = self.toks[ls]
            loc = Loc(first_tok.file, first_tok.line, first_tok.column)
            callstack = []
            # assignment note for the variable side with known value
            for (s, e) in ((ls, le), (rs, re_)):
                toks = self.toks[s:e]
                if len(toks) == 1 and toks[0].kind == "id":
                    vv = self.resolve_var(toks[0].text, s, self.cur_function)
                    if vv is not None:
                        vst = self.get_state(vv)
                        if vst.known_token is not None:
                            kt = vst.known_token
                            if note_kind == "assigned":
                                info_n = f"'{vv.name}' is assigned value '{vst.known}' here."
                            else:
                                info_n = f"Assignment '{vv.name}={vst.known_rhs_text}', assigned value is {vst.known}"
                            callstack.append(Loc(kt.file, kt.line, kt.column, info_n))
                            break
            callstack.append(Loc(first_tok.file, first_tok.line, first_tok.column, msg))
            d = make_diag("knownConditionTrueFalse", msg, loc, severity="style", info=msg,
                          callstack=callstack, has_notes=bool(len(callstack)>1))
            self.diags.append(d)
            if self.is_in_condition(ls): self.known_if_count += 1

    def _check_bool_compare(self, op_idx, ls, le, rs, re_):
        op = self.toks[op_idx].text
        # find bool var side and integer literal side
        for (s, e, os_, oe, bool_is_left) in ((ls, le, rs, re_, True), (rs, re_, ls, le, False)):
            toks = self.toks[s:e]
            otoks = self.toks[os_:oe]
            if len(toks) == 1 and toks[0].kind == "id" and len(otoks) == 1 and otoks[0].kind == "num" and isinstance(otoks[0].value, int):
                vv = self.resolve_var(toks[0].text, s, self.cur_function)
                oval = otoks[0].value
                if vv is not None and vv.is_bool() and self.language == "cpp":
                    if oval not in (0, 1) or op in ("<", "<=", ">", ">="):
                        loc = Loc(self.toks[op_idx].file, self.toks[op_idx].line, self.toks[op_idx].column)
                        self.diags.append(make_diag("compareBoolExpressionWithInt", "Comparison of a boolean expression with an integer.", loc, severity="warning"))
                    # range error if value outside bool or comparison predetermined by type
                    # bool values are 0/1
                    always = None
                    if bool_is_left:
                        if op == ">" and oval >= 1: always = False
                        elif op == "<" and oval <= 0: always = False
                        elif op == ">=" and oval <= 0: always = True
                        elif op == "<=" and oval >= 1: always = True
                        elif op == "==" and (oval > 1 or oval < 0): always = False
                        elif op == "!=" and (oval > 1 or oval < 0): always = True
                    if always is not None and oval not in (0,1) or (op in (">",) and oval == 1):
                        # only report range for out-of-range style as in observed b>1 (oval==1 and > gives false because bool <=1, actually oval==1)
                        loc = Loc(otoks[0].file, otoks[0].line, otoks[0].column)
                        msg = f"Comparing expression of type 'bool' against value {oval}. Condition is always {'true' if always else 'false'}."
                        self.diags.append(make_diag("compareValueOutOfTypeRangeError", msg, loc, severity="style"))
                elif vv is not None and (vv.is_char() or (vv.is_unsigned() and vv.type_width() <= 16) or vv.type_width() <= 8):
                    # small type range check
                    w = vv.type_width()
                    if vv.is_unsigned(): lo_r, hi_r = 0, (1<<w)-1
                    else: lo_r, hi_r = (-(1<<(w-1)), (1<<(w-1))-1)
                    always = None
                    if bool_is_left:
                        if op == ">" and oval >= hi_r: always = False
                        elif op == "<" and oval <= lo_r: always = False
                        elif op == "==" and (oval > hi_r or oval < lo_r): always = False
                        elif op == "!=" and (oval > hi_r or oval < lo_r): always = True
                        elif op == ">=" and oval <= lo_r: always = True
                        elif op == "<=" and oval >= hi_r: always = True
                    if always is not None:
                        tname = vv.type_text()
                        loc = Loc(otoks[0].file, otoks[0].line, otoks[0].column)
                        msg = f"Comparing expression of type '{tname}' against value {oval}. Condition is always {'true' if always else 'false'}."
                        self.diags.append(make_diag("compareValueOutOfTypeRangeError", msg, loc, severity="style"))
                break

