    def _format_specs(self, fmt):
        specs = []
        i = 0
        while i < len(fmt):
            if fmt[i] != "%":
                i += 1; continue
            if i+1 < len(fmt) and fmt[i+1] == "%":
                i += 2; continue
            j = i+1; stars = 0
            while j < len(fmt) and fmt[j] in "-+ #0'": j += 1
            while j < len(fmt) and (fmt[j].isdigit() or fmt[j] == "*"):
                if fmt[j] == "*": stars += 1
                j += 1
            if j < len(fmt) and fmt[j] == ".":
                j += 1
                while j < len(fmt) and (fmt[j].isdigit() or fmt[j] == "*"):
                    if fmt[j] == "*": stars += 1
                    j += 1
            length = ""
            for lm in ("hh","ll","h","l","j","z","t","L"):
                if fmt.startswith(lm, j): length = lm; j += len(lm); break
            if j >= len(fmt): break
            conv = fmt[j]
            if conv in "diouxXeEfFgGaAcspn%":
                specs.append({"raw": "%" + length + conv, "conv": conv, "length": length, "stars": stars, "width": None})
                # capture numeric width for scanf
                mwidth = re.search(r"%(\d+)", fmt[i:j])
                if mwidth: specs[-1]["width"] = int(mwidth.group(1))
            i = j + 1
        return specs

    def _arg_type(self, s, e):
        toks = self.toks[s:e]
        if not toks: return None
        if len(toks) == 1:
            t = toks[0]
            if t.kind == "str": return "char *"
            if t.kind == "char": return "char"
            if t.kind == "num":
                return "double" if isinstance(t.value, float) else "int"
            if t.kind == "id":
                if t.text in ("true","false"): return "bool"
                v = self.resolve_var(t.text, s, self.cur_function)
                if v is not None:
                    words = v.base_words()
                    base = words[-1] if words else ""
                    if v.is_array:
                        return (base + " *") if base else None
                    if v.pointer:
                        return (base + " *") if base else None
                    if base in ("int","char","short","long","float","double","bool","size_t"):
                        if "unsigned" in [x.text for x in v.type_tokens]:
                            return "unsigned int" if base in ("int","char","short","long") else base
                        return base
                    if base: return base
                return None
        if toks[0].text == "&" and len(toks) >= 2:
            inner = self._arg_type(s+1, e)
            return (inner + " *") if inner else None
        if toks[0].kind == "str": return "char *"
        return None

    def _check_format_call(self, name, fn_tok, args):
        is_scanf = name in ("scanf","fscanf","sscanf")
        fmt_idx = 0
        if name in ("fprintf","fscanf","sprintf"): fmt_idx = 1
        if name in ("snprintf","vsnprintf"): fmt_idx = 2
        if fmt_idx >= len(args): return
        fs, fe = args[fmt_idx]
        fmt_toks = self.toks[fs:fe]
        if len(fmt_toks) != 1 or fmt_toks[0].kind != "str": return
        fmt = fmt_toks[0].value or ""
        specs = self._format_specs(fmt)
        value_args = args[fmt_idx+1:]
        total_needed = len(specs)
        # positional / star args ignored in count approximation
        if len(value_args) < total_needed:
            loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
            msg = f"{name} format string requires {total_needed} parameters but only {len(value_args)} are given."
            self.diags.append(make_diag("wrongPrintfScanfArgNum", msg, loc))
            return
        if is_scanf:
            # invalidscanf: %s / %[ without width
            for sp in specs:
                if sp["conv"] in ("s", "[") and sp["width"] is None:
                    loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                    _, _, verb = info_for("invalidscanf")
                    self.diags.append(make_diag("invalidscanf", "scanf() without field width limits can crash with huge input data.", loc,
                                                severity="warning", verbose=verb))
                    break
            for idx, sp in enumerate(specs):
                if idx >= len(value_args): break
                s, e = value_args[idx]
                at = self._arg_type(s, e)
                toks = self.toks[s:e]
                is_ptr = False
                if toks and toks[0].text == "&": is_ptr = True
                elif at and at.endswith("*"): is_ptr = True
                else:
                    # array name is pointer-like
                    if len(toks) == 1 and toks[0].kind == "id":
                        v = self.resolve_var(toks[0].text, s, self.cur_function)
                        if v is not None and (v.is_array or v.pointer): is_ptr = True
                if not is_ptr and at:
                    conv = sp["conv"]
                    if conv in "diouxX":
                        eid = "invalidScanfArgType_int"; exp = "int *"
                    elif conv in "fFeEgGaA":
                        eid = "invalidScanfArgType_float"; exp = "float *"
                    elif conv in "s":
                        eid = "invalidScanfArgType_s"; exp = "char *"
                    else: continue
                    loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                    msg = f"{sp['raw']} in format string (no. {idx+1}) requires '{exp}' but the argument type is '{at}'."
                    self.diags.append(make_diag(eid, msg, loc, severity="warning"))
            return
        # printf types
        # sprintf overlapping
        if name in ("sprintf","snprintf") and args:
            ds, de = args[0]
            dst_ids = [x.text for x in self.toks[ds:de] if x.kind == "id"]
            for (s, e) in value_args:
                ids = [x.text for x in self.toks[s:e] if x.kind == "id"]
                if dst_ids and any(x in dst_ids for x in ids):
                    loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
                    msg = f"Undefined behavior: Variable '{dst_ids[0]}' is used as parameter and destination in s[n]printf()."
                    self.diags.append(make_diag("sprintfOverlappingData", msg, loc, symbol=dst_ids[0]))
                    break
        for idx, sp in enumerate(specs):
            if idx >= len(value_args): break
            s, e = value_args[idx]
            at = self._arg_type(s, e)
            if not at: continue
            conv = sp["conv"]
            checks = {
                "d": ("invalidPrintfArgType_sint", "int", {"int","char","short","bool"}),
                "i": ("invalidPrintfArgType_sint", "int", {"int","char","short","bool"}),
                "c": ("invalidPrintfArgType_sint", "int", {"int","char","short","bool"}),
