    def _dest_array(self, arg_range):
        s, e = arg_range
        toks = self.toks[s:e]
        if not toks: return None, None
        # &a[0] etc: first id
        for t in toks:
            if t.kind == "id":
                v = self.resolve_var(t.text, s, self.cur_function)
                if v is not None and v.is_array and v.array_size is not None:
                    elem = 4 if any(x.text in ("int","float") for x in v.type_tokens) else 1
                    if any(x.text in ("long","double") for x in v.type_tokens): elem = 8
                    if any(x.text == "short" for x in v.type_tokens): elem = 2
                    return v, v.array_size * elem
                if v is not None:
                    return v, None
        return None, None

    def _src_len(self, arg_range):
        s, e = arg_range
        toks = self.toks[s:e]
        if len(toks) == 1 and toks[0].kind == "str":
            return len(toks[0].value or "")
        v, sz = self._dest_array(arg_range)
        if v is not None and v.init_tokens and len(v.init_tokens) == 1 and v.init_tokens[0].kind == "str":
            return len(v.init_tokens[0].value or "")
        if v is not None:
            st = self.get_state(v)
            if st.string_token is not None:
                return len(st.string_token.value or "")
        return None

    def _check_buffer_call(self, name, fn_tok, args):
        if not args: return
        dst, dst_size = self._dest_array(args[0])
        if dst is None: return
        loc = Loc(fn_tok.file, fn_tok.line, fn_tok.column)
        def report():
            msg = f"Buffer is accessed out of bounds: {dst.name}"
            self.diags.append(make_diag("bufferAccessOutOfBounds", msg, loc))
        if name == "strcpy" and len(args) >= 2 and dst_size is not None:
            sl = self._src_len(args[1])
            if sl is not None and sl + 1 > dst_size: report()
        elif name == "strcat" and len(args) >= 2 and dst_size is not None:
            sl = self._src_len(args[1])
            cur = self._src_len(args[0]) or 0
            if sl is not None and cur + sl + 1 > dst_size: report()
        elif name in ("memcpy","memmove","strncpy") and len(args) >= 3 and dst_size is not None:
            n = self.eval_range(args[2][0], args[2][1])
            if isinstance(n, int) and n > dst_size: report()
        elif name == "memset" and len(args) >= 3 and dst_size is not None:
            n = self.eval_range(args[2][0], args[2][1])
            if isinstance(n, int) and n > dst_size: report()

