    def handle_operator(self, i, end):
        t = self.toks[i]; op = t.text
        in_loop_header = any(s <= i <= e for (s, e) in self.loop_header_ranges)
        if op in ("/", "%"):
            rs, re_ = self.primary_after(i, end)
            if rs < re_:
                val = self.eval_range(rs, re_)
                if isinstance(val, (int,float)) and val == 0:
                    loc = Loc(t.file, t.line, t.column)
                    callstack = []
                    # variable divisor with known assignment
                    if re_ - rs == 1 and self.toks[rs].kind == "id":
                        vv = self.resolve_var(self.toks[rs].text, rs, self.cur_function)
                        if vv is not None:
                            vst = self.get_state(vv)
                            if vst.known_token is not None:
                                kt = vst.known_token
                                callstack.append(Loc(kt.file, kt.line, kt.column, f"Assignment '{vv.name}={vst.known_rhs_text}', assigned value is 0"))
                    callstack.append(Loc(t.file, t.line, t.column, "Division by zero"))
                    d = make_diag("zerodiv", "Division by zero.", loc, info="Division by zero",
                                  callstack=callstack, has_notes=bool(len(callstack) > 1))
                    self.diags.append(d)
            return
        if op in ("<<", ">>"):
            rs, re_ = self.primary_after(i, end)
            ls, le = self.primary_before(i)
            amt = self.eval_range(rs, re_) if rs < re_ else None
            lval = self.eval_range(ls, le) if ls < le else None
            # determine LHS width / signed
            bits = 32; signed = True
            if ls < le:
                # literal suffix / value
                first = self.toks[ls]
                if first.kind == "id":
                    vv = self.resolve_var(first.text, ls, self.cur_function)
                    if vv is not None:
                        bits = vv.type_width(); signed = not vv.is_unsigned()
                    if first.text.endswith("_t"): bits = 32
                elif first.kind == "num":
                    raw = first.text.lower()
                    if "ll" in raw: bits = 64
                    elif "l" in raw: bits = 64
                    if "u" in raw: signed = False
                    if isinstance(first.value, int) and (first.value > 2**31 or first.value < -2**31): bits = 64
            if isinstance(amt, int):
                if amt < 0:
                    loc = Loc(t.file, t.line, t.column)
                    self.diags.append(make_diag("shiftNegative", "Shifting by a negative value is undefined behaviour", loc))
                elif amt >= bits:
                    loc = Loc(t.file, t.line, t.column)
                    self.diags.append(make_diag("shiftTooManyBits", f"Shifting {bits}-bit value by {amt} bits is undefined behaviour", loc))
                elif signed and amt == bits - 1 and isinstance(lval, int) and lval > 0:
                    loc = Loc(t.file, t.line, t.column)
                    self.diags.append(make_diag("shiftTooManyBitsSigned", f"Shifting signed {bits}-bit value by {amt} bits is undefined behaviour", loc))
                # integer overflow for <<
                if op == "<<" and signed and isinstance(lval, int) and isinstance(amt, int) and 0 <= amt < 128:
                    res = lval << amt
                    lo, hi = (-(1 << (bits-1)), (1 << (bits-1)) - 1)
                    if res > hi or res < lo:
                        loc = Loc(t.file, t.line, t.column)
                        ex = expr_text(self.toks[ls:le]) + op + expr_text(self.toks[rs:re_])
                        self.diags.append(make_diag("integerOverflow", f"Signed integer overflow for expression '{ex}'.", loc))
            return
        if op in ("+", "-", "*") and op != "*":
            # skip pointer deref/mult ambiguity for *: primary extraction may still work for numbers
            ls, le = self.primary_before(i); rs, re_ = self.primary_after(i, end)
