    # ---- generic scans ----
    def generic_scans(self):
        self._scan_duplicate_expressions()
        self._scan_conditions()
        self._scan_sizeof_cast_etc()
        self._scan_unreachable()
        self._scan_shadow()
        self._scan_member_function_static()
        # extra assignments unread (member/array elements)
        if self.cur_function is None:
            pass
        # handled per-function below in process? Do it here for all functions based on records gathered during their processing.
        # extra_assignments records are shared across functions; their var has .function
        for key, rec in list(getattr(self, "extra_assignments", {}).items()):
            if not rec.get("read", True) and rec.get("token") is not None:
