    # ---- return / catch / other per-statement checks ----
    def check_return(self, i, end):
        if self.cur_function is None: return
        f = self.cur_function
        # statement range
        stmt_end = self.find_expr_end(i+1, end)
        toks = self.toks[i+1:stmt_end]
        if not toks: return
        ret_is_ptr = any(x.text == "*" for x in f.ret_tokens)
        ret_is_ref = any(x.text in ("&","&&") for x in f.ret_tokens)
        # return &local
        if len(toks) >= 2 and toks[0].text == "&" and toks[1].kind == "id":
            v = self.resolve_var(toks[1].text, i+1, f)
            if v is not None and not v.is_global and not v.is_param and not v.is_static and not v.is_member:
                amp = toks[0]
                loc = Loc(amp.file, amp.line, amp.column)
                msg = f"Returning pointer to local variable '{v.name}' that will be invalid when returning."
                decl = v.decl_token
                callstack = [Loc(amp.file, amp.line, amp.column, "Address of variable taken here."),
                             Loc(decl.file, decl.line, decl.column, "Variable created here."),
                             Loc(amp.file, amp.line, amp.column, msg)]
                d = make_diag("returnDanglingLifetime", msg, loc, info=msg, callstack=callstack, has_notes=True, symbol=v.name)
                self.diags.append(d)
            return
        if len(toks) == 1 and toks[0].kind == "id":
            v = self.resolve_var(toks[0].text, i+1, f)
            if v is None: return
            if ret_is_ref and not v.is_global and not v.is_param and not v.is_static:
                loc = Loc(toks[0].file, toks[0].line, toks[0].column)
                self.diags.append(make_diag("returnReference", "Reference to local variable returned.", loc, symbol=v.name))
            elif ret_is_ptr and v.is_array and not v.is_global:
                loc = Loc(toks[0].file, toks[0].line, toks[0].column)
                msg = f"Returning pointer to local variable '{v.name}' that will be invalid when returning."
                self.diags.append(make_diag("returnDanglingLifetime", msg, loc, symbol=v.name))
            # mark allocation escape on return
            st = self.get_state(v)
            if st.alloc: st.alloc.escaped = True; st.alloc.used = True
            st.returned = True
        else:
            # general: returned allocation pointer variable inside expression
            for tk in toks:
                if tk.kind == "id":
                    v = self.resolve_var(tk.text, self.index_map.get(id(tk), i), f)
                    if v is not None:
                        st = self.get_state(v)
                        if st.alloc: st.alloc.escaped = True; st.alloc.used = True

    def check_catch(self, i):
        if self.language != "cpp": return
        if i+1 < len(self.toks) and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
            pc = self.match_paren[i+1]
            inner = self.toks[i+2:pc]
            if not inner: return
            vs = self.parse_segment_vars(inner, function=self.cur_function, is_param=True)
            if vs:
                v = vs[0]
                words = v.base_words()
                if v.pointer == 0 and not v.is_ref and words:
                    last = words[-1]
                    if last not in TYPE_KEYWORDS:
                        t = self.toks[i]
                        loc = Loc(t.file, t.line, t.column)
                        self.diags.append(make_diag("catchExceptionByValue", "Exception should be caught by reference.", loc, severity="style"))

    # ---- generic scans ----
    def generic_scans(self):
        self._scan_duplicate_expressions()
        self._scan_conditions()
        self._scan_sizeof_cast_etc()
        self._scan_unreachable()
        self._scan_shadow()
        self._scan_member_function_static()
        # extra assignments unread (member/array elements)
        if self.cur_function is None:
            pass
        # handled per-function below in process? Do it here for all functions based on records gathered during their processing.
        # extra_assignments records are shared across functions; their var has .function
        for key, rec in list(getattr(self, "extra_assignments", {}).items()):
            if not rec.get("read", True) and rec.get("token") is not None:
                tok = rec["token"]
                loc = Loc(tok.file, tok.line, tok.column)
                expr = rec.get("expr", "")
                d = make_diag("unreadVariable", f"Variable '{expr}' is assigned a value that is never used.", loc, severity="style", symbol=expr)
                self.diags.append(d)

    def _scan_duplicate_expressions(self):
        n = len(self.toks)
        for i, t in enumerate(self.toks):
            if t.text in ("&&","||","-","&","|","^","==","!="):
                # skip if inside a for header (handled)
                ls, le = self.primary_before(i); rs, re_ = self.primary_after(i)
                if ls >= le or rs >= re_: continue
                lt = expr_text(self.toks[ls:le]); rt = expr_text(self.toks[rs:re_])
                if lt and lt == rt and lt not in ("0","1"):
                    loc = Loc(t.file, t.line, t.column)
                    msg = f"Same expression on both sides of '{t.text}'."
                    self.diags.append(make_diag("duplicateExpression", msg, loc, severity="style"))
                    if t.text in ("&&","||") and self.resolve_var(lt, ls, None) is not None or True:
                        # known second operand
                        loc2_tok = self.toks[rs]
                        loc2 = Loc(loc2_tok.file, loc2_tok.line, loc2_tok.column)
                        val = (t.text == "&&")
                        msg2 = f"Condition '{rt}' is always {'true' if val else 'false'}"
                        # Only for simple identifiers / expressions that are conditions
                        # Heuristic: only when the duplicate is in a condition context
                        if self.is_in_condition(i):
                            d2 = make_diag("knownConditionTrueFalse", msg2, loc2, severity="style")
                            self.diags.append(d2)
            if t.text == "?":
                # find ':'
                depth = 0; colon = -1
                for k in range(i+1, n):
                    if self.toks[k].text == "?": depth += 1
                    elif self.toks[k].text == ":":
                        if depth == 0: colon = k; break
                        depth -= 1
                    elif self.toks[k].text in (";", "}") and depth == 0:
                        break
                if colon > 0:
                    left = self.toks[i+1:colon]
                    rend = self.find_expr_end(colon+1, n)
                    right = self.toks[colon+1:rend]
                    if left and right and expr_text(left) == expr_text(right):
                        tok = right[0]
                        loc = Loc(tok.file, tok.line, tok.column)
                        self.diags.append(make_diag("duplicateExpressionTernary", "Same expression in both branches of ternary operator.", loc, severity="style"))

    def _scan_conditions(self):
        # duplicate condition / multi condition
        last_cond = None  # (text, tok, line)
        chain_cond = None
        n = len(self.toks)
        for i, t in enumerate(self.toks):
            if t.text == "else" and i+1 < n and self.toks[i+1].text == "if":
                continue
            if t.text == "if":
                is_elseif = i > 0 and self.toks[i-1].text == "else"
                if i+1 < n and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
                    pc = self.match_paren[i+1]
                    cond_toks = self.toks[i+2:pc]
                    ctxt = expr_text(cond_toks)
                    ctok = cond_toks[0] if cond_toks else t
                    if is_elseif:
                        if chain_cond and ctxt == chain_cond[0]:
                            loc = Loc(ctok.file, ctok.line, ctok.column)
                            msg = f"Expression is always false because 'else if' condition matches previous condition at line {chain_cond[2]}."
                            self.diags.append(make_diag("multiCondition", msg, loc, severity="style"))
                    else:
                        if last_cond and ctxt == last_cond[0] and ctxt:
                            loc = Loc(ctok.file, ctok.line, ctok.column)
                            msg = "The if condition is the same as the previous if condition"
                            callstack = [Loc(last_cond[1].file, last_cond[1].line, last_cond[1].column, "First condition"),
                                         Loc(ctok.file, ctok.line, ctok.column, "Second condition")]
                            d = make_diag("duplicateCondition", msg, loc, severity="style", info=msg, callstack=callstack, has_notes=True)
                            self.diags.append(d)
                        chain_cond = (ctxt, ctok, ctok.line)
                    last_cond = (ctxt, ctok, ctok.line)

    def _scan_sizeof_cast_etc(self):
        n = len(self.toks)
        for i, t in enumerate(self.toks):
            if t.text == "sizeof" and i+1 < n and self.toks[i+1].text == "(" and (i+1) in self.match_paren:
                pc = self.match_paren[i+1]
                inner = self.toks[i+2:pc]
                loc = Loc(t.file, t.line, t.column)
                if inner and inner[0].text == "sizeof":
                    self.diags.append(make_diag("sizeofsizeof", "Calling 'sizeof' on 'sizeof'.", loc, severity="warning"))
                elif len(inner) == 1 and inner[0].kind == "num":
                    self.diags.append(make_diag("sizeofwithnumericparameter", "Suspicious usage of 'sizeof' with a numeric constant as parameter.", loc, severity="warning"))
                elif any(x.text == "(" and inner[j].kind == "id" for j, x in enumerate(inner) if x.text == "("):
                    self.diags.append(make_diag("sizeofFunctionCall", "Found function call inside sizeof().", loc, severity="warning"))
                elif any(x.text in ("+","-","*","/","%") for x in inner):
                    self.diags.append(make_diag("sizeofCalculation", "Found calculation inside sizeof().", loc, severity="warning"))
            if self.language == "cpp" and t.text == "(" and i+1 < n:
                # C-style pointer cast
                if i in self.match_paren:
                    pc = self.match_paren[i]
                    inner = self.toks[i+1:pc]
                    if inner and any(x.text in ("*", "&") for x in inner) and all((x.kind=="id" or x.text in TYPE_KEYWORDS or x.text in ("*","&","::","<",">",",","const")) for x in inner):
                        prev = self.toks[i-1] if i > 0 else None
                        if prev is not None and prev.text in ("=","(",";",",","return","[","+","-","*","/","=="):
                            if pc+1 < n and (self.toks[pc+1].kind in ("id","num") or self.toks[pc+1].text == "("):
                                tok = inner[0]
                                loc = Loc(tok.file, tok.line, tok.column)
                                self.diags.append(make_diag("cstyleCast", "C-style pointer casting", loc, severity="style"))
            if t.kind == "str" and i+2 < n and self.toks[i+1].text == "+":
                nt = self.toks[i+2]
                if nt.kind == "char" or (nt.kind == "id"):
                    is_char = nt.kind == "char"
                    if not is_char and nt.kind == "id":
                        vv = self.resolve_var(nt.text, i+2, None)
                        if vv is not None and vv.is_char(): is_char = True
                    if is_char:
                        op = self.toks[i+1]
                        loc = Loc(op.file, op.line, op.column)
                        self.diags.append(make_diag("strPlusChar", "Unusual pointer arithmetic. A value of type 'char' is added to a string literal.", loc))
            if t.kind == "char" and i+2 < n and self.toks[i+1].text == "+" and self.toks[i+2].kind == "str":
                op = self.toks[i+1]
                loc = Loc(op.file, op.line, op.column)
                self.diags.append(make_diag("strPlusChar", "Unusual pointer arithmetic. A value of type 'char' is added to a string literal.", loc))

    def _scan_unreachable(self):
        # examine each brace block
        for (bs, be) in list(self.match_brace.items()):
            if bs > be: continue
            # only code blocks: function bodies or blocks following ) / else / do / { etc - accept all braces except class/initializer (heuristic: skip class starts)
            if any(ci.start == bs for ci in self.classes): continue
            stmts = []
            pos = bs + 1
            while pos < be:
                if self.toks[pos].text == ";":
                    pos += 1; continue
                e = self.statement_range(pos)
                if e <= pos: break
                stmts.append((pos, e))
                pos = e
            prev_term = None
            for (s, e) in stmts:
                first = self.toks[s]
                if prev_term is not None:
                    if first.text in ("case", "default") or (first.kind == "id" and s+1 < e and self.toks[s+1].text == ":"):
                        prev_term = None
                    elif first.text in ("return","break","continue","goto","throw"):
                        loc = Loc(first.file, first.line, first.column)
                        self.diags.append(make_diag("duplicateBreak", "Consecutive return, break, continue, goto or throw statements are unnecessary.", loc, severity="style"))
                        prev_term = first.text
                        continue
                    else:
                        loc = Loc(first.file, first.line, first.column)
                        msg = f"Statements following '{prev_term}' will never be executed."
                        self.diags.append(make_diag("unreachableCode", msg, loc, severity="style"))
                        prev_term = None
                        # continue; subsequent statements are also unreachable in reality but cpp reports once per block segment
                        # keep prev_term None so only first unreachable reported
                if first.text in ("return","break","continue","goto","throw"):
                    prev_term = first.text
                else:
                    prev_term = None

    def _scan_shadow(self):
        globals_by_name = {v.name: v for v in self.global_vars}
        for v in self.local_vars:
            if v.is_param or v.is_member: continue
            outer = None
            if v.name in globals_by_name and globals_by_name[v.name] is not v:
                outer = globals_by_name[v.name]
            else:
                # outer local in enclosing scope
                if v.function is not None:
                    for o in self.local_vars:
                        if o is v or o.name != v.name: continue
                        if o.function is v.function and o.decl_index < v.decl_index and o.scope_start <= v.scope_start and o.scope_end >= v.scope_end and o.scope_start < v.scope_start:
                            outer = o; break
                        if o.is_param and v.function is o.function:
                            outer = o; break
            if outer is not None and v.decl_token is not None and outer.decl_token is not None:
                loc = Loc(v.decl_token.file, v.decl_token.line, v.decl_token.column)
                msg = f"Local variable '{v.name}' shadows outer variable"
                callstack = [Loc(outer.decl_token.file, outer.decl_token.line, outer.decl_token.column, "Shadowed declaration"),
                             Loc(v.decl_token.file, v.decl_token.line, v.decl_token.column, "Shadow variable")]
                d = make_diag("shadowVariable", msg, loc, severity="style", info=msg, callstack=callstack, has_notes=True, symbol=v.name)
                self.diags.append(d)

    def _scan_member_function_static(self):
        if self.language != "cpp": return
        for f in self.functions:
            if not f.is_member or not f.class_name: continue
            if f.name == f.class_name or f.name.startswith("~"): continue
            if any(x.text in ("static","virtual") for x in f.ret_tokens): continue
            ci = next((c for c in self.classes if c.name == f.class_name), None)
            member_names = set()
            if ci:
                member_names = {m.name for m in ci.members}
                member_names |= {mf.name for mf in self.functions if mf.is_member and mf.class_name == f.class_name}
            body_toks = self.toks[f.body_start:f.body_end+1] if f.body_start >= 0 else []
            uses_member = any(tok.text == "this" or (tok.kind == "id" and tok.text in member_names) for tok in body_toks)
            if not uses_member:
                loc = Loc(f.name_token.file, f.name_token.line, f.name_token.column)
                msg = f"The member function '{f.class_name}::{f.name}' can be static."
                self.diags.append(make_diag("functionStatic", msg, loc, severity="style", symbol=f"{f.class_name}::{f.name}"))

    def check_unused_struct_members(self):
        if not self.classes: return
        accessed = set()
        for i, t in enumerate(self.toks):
            if i > 0 and self.toks[i-1].text in (".", "->") and t.kind == "id":
                accessed.add(t.text)
        for ci in self.classes:
            for m in ci.members:
                if m.name not in accessed and m.decl_token is not None:
                    loc = Loc(m.decl_token.file, m.decl_token.line, m.decl_token.column)
                    msg = f"struct member '{ci.name}::{m.name}' is never used."
                    self.diags.append(make_diag("unusedStructMember", msg, loc, severity="style", symbol=f"{ci.name}::{m.name}"))

    def check_no_constructors(self):
        for ci in self.classes:
            if ci.keyword != "class": continue
            if not ci.members: continue
            if ci.has_ctor: continue
            if not ci.has_private_var: continue
            t = ci.keyword_token
            if t:
                loc = Loc(t.file, t.line, t.column)
                msg = f"The class '{ci.name}' does not declare a constructor although it has private member variables which likely require initialization."
                self.diags.append(make_diag("noConstructor", msg, loc, severity="style", symbol=ci.name))

    def check_const_candidates(self, f):
        # locals and params of this function
        vars_ = [v for v in self.local_vars if v.function is f]
        for v in vars_:
            st = self.get_state(v)
            if v.pointer == 1 and not v.is_ref and not v.const_pointee:
                if st.written_through or st.passed_to_func and False:
                    pass
                # Determine written-through / escape by searching tokens in body
                written, passed_unknown, returned = self._pointer_usage(v, f)
                if not written and not passed_unknown and not returned:
                    loc = Loc(v.decl_token.file, v.decl_token.line, v.decl_token.column)
                    if v.is_param:
                        d = make_diag("constParameterPointer", f"Parameter '{v.name}' can be declared as pointer to const", loc, severity="style", symbol=v.name)
                    else:
                        d = make_diag("constVariablePointer", f"Variable '{v.name}' can be declared as pointer to const", loc, severity="style", symbol=v.name)
                    self.diags.append(d)
            if v.is_ref and self.language == "cpp":
                if v.const_pointee or any(t.text == "const" for t in v.type_tokens):
                    continue
                written, passed_unknown, returned, method_call = self._ref_usage(v, f)
                if not written and not passed_unknown and not method_call:
                    loc = Loc(v.decl_token.file, v.decl_token.line, v.decl_token.column)
                    if v.is_param:
                        d = make_diag("constParameterReference", f"Parameter '{v.name}' can be declared as reference to const", loc, severity="style", symbol=v.name)
                    else:
                        d = make_diag("constVariableReference", f"Variable '{v.name}' can be declared as reference to const", loc, severity="style", symbol=v.name)
                    self.diags.append(d)
            if st.alloc is not None:
                pass

    def _pointer_usage(self, v, f):
        written = False; passed_unknown = False; returned = False
        s, e = f.body_start, f.body_end
        for i in range(s, e+1):
            tok = self.toks[i]
            if tok.kind == "id" and tok.text == v.name:
                # *v = / v[...] = / v->x =
                if i > s and self.toks[i-1].text == "*" and self._is_unary_at(i-1):
                    if i+1 <= e and self.toks[i+1].text == "=": written = True
                if i+1 <= e and self.toks[i+1].text == "[":
                    if (i+1) in self.match_bracket:
                        cb = self.match_bracket[i+1]
                        if cb+1 <= e and self.toks[cb+1].text == "=": written = True
                if i+2 <= e and self.toks[i+1].text == "->" and i+3 <= e and self.toks[i+3].text == "=":
                    written = True
                # passed as function argument: inside parentheses preceded by ( or ,
                # find if token is argument of a call (enclosing '(' preceded by function name)
                # heuristic: previous token is '(' or ',' and a call is enclosing - mark unknown unless known const funcs
                if i > s and self.toks[i-1].text in ("(", ","):
                    # determine callee name by scanning to matching '(' backward
                    # simple: mark as passed unknown unless surroundings are return / assignment etc
                    passed_unknown = True
                if i > s and self.toks[i-1].text == "return":
                    returned = True
        # known escapes from state
        st = self.get_state(v)
        if st.alloc and st.alloc.escaped: passed_unknown = True
        if st.returned: returned = True
        if st.written_through: written = True
        return written, passed_unknown, returned

    def _ref_usage(self, v, f):
        written = False; passed_unknown = False; returned = False; method_call = False
        s, e = f.body_start, f.body_end
        for i in range(s, e+1):
            tok = self.toks[i]
            if tok.kind == "id" and tok.text == v.name and not (i in self.decl_name_idx):
                if i+1 <= e and self.toks[i+1].text in ("=", "+=", "-=", "++", "--"):
                    written = True
                if i+1 <= e and self.toks[i+1].text in (".", "->"):
                    # member assignment or method call
                    if i+3 <= e and self.toks[i+3].text == "(": method_call = True
                    elif i+3 <= e and self.toks[i+3].text == "=": written = True
                if i > s and self.toks[i-1].text in ("(", ","):
                    passed_unknown = True
        return written, passed_unknown, returned, method_call

    def check_missing_return(self, f):
        if f.name == "main": return
        if f.class_name and (f.name == f.class_name or f.name == "~" + f.class_name): return
        ret_words = [t.text for t in f.ret_tokens if t.text not in ("static","inline","virtual","constexpr","explicit","friend")]
        if not ret_words: return
        if len(ret_words) == 1 and ret_words[0] == "void": return
        if f.body_start < 0: return
        # last statement always returns?
        if self._block_always_returns(f.body_start, f.body_end):
            return
        tok = self.toks[f.body_end]
        loc = Loc(tok.file, tok.line, tok.column)
        msg = "Found an exit path from function with non-void return type that has missing return statement"
        self.diags.append(make_diag("missingReturn", msg, loc))

    def _block_always_returns(self, bs, be):
        # bs is '{' token index, be its '}'
        stmts = []
        pos = bs + 1
        while pos < be:
            if self.toks[pos].text == ";": pos += 1; continue
            e = self.statement_range(pos)
            if e <= pos: break
            stmts.append((pos, e)); pos = e
        if not stmts: return False
        return self._stmt_always_returns(stmts[-1][0], stmts[-1][1])
    def _stmt_always_returns(self, s, e):
        if s >= e: return False
        t = self.toks[s]
        if t.text == "return": return True
        if t.text == "{" and s in self.match_brace:
            return self._block_always_returns(s, self.match_brace[s])
        if t.text == "if":
            # if ... else ... both return
            if s+1 < e and self.toks[s+1].text == "(" and (s+1) in self.match_paren:
                pc = self.match_paren[s+1]
                then_e = self.statement_range(pc+1)
                if then_e < e and self.toks[then_e].text == "else":
                    else_s = then_e + 1; else_e = self.statement_range(else_s)
                    return self._stmt_always_returns(pc+1, then_e) and self._stmt_always_returns(else_s, else_e)
            return False
        return False

