# ---------- formatting diagnostics ----------
def xml_escape(s, attr=True):
    s = str(s)
    s = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    if attr:
        s = s.replace('"', "&quot;").replace("'", "&apos;")
        s = s.replace("\n", "&#10;").replace("\r", "&#13;")
    return s

def caret_line(col):
    return " " * max(0, col - 1) + "^"

def render_default_like(d, severity_disp, include_id, include_code, file_fallback=True):
    file_disp = d.file if d.file else ("nofile" if file_fallback else "")
    head = f"{file_disp}:{d.line}:{d.column}: {severity_disp}: {d.msg}"
    if include_id:
        head += f" [{d.id}]"
    code = get_line_text(d.file, d.line) if d.file else None
    if include_code and code is not None:
        return head + "\n" + code + "\n" + caret_line(d.column) + "\n"
    if include_code and d.file and d.file in FILE_LINES:
        # line 0 with real file
        return head + "\n\n^\n"
    if include_code:
        return head + "\n\n"
    return head + "\n"

def template_substitute(tmpl, values):
    s = tmpl.replace("\\t", "\t").replace("\\r", "\r").replace("\\n", "\n")
    def repl(m):
        name = m.group(1)
        arg = m.group(2)
        if name == "inconclusive":
            return values.get("inconclusive_text", "") if values.get("is_inconclusive") else ""
            # arg handling done below
        if name in values:
            return str(values[name])
        return m.group(0)
    # inconclusive form {inconclusive:text}
    def repl_inc(m):
        return m.group(1) if values.get("is_inconclusive") else ""
    s = re.sub(r"\{inconclusive:([^}]*)\}", repl_inc, s)
    s = re.sub(r"\{([A-Za-z]+)(?::([^}]*))?\}", lambda m: str(values.get(m.group(1), m.group(0))), s)
    return s

def render_text_diag(d, settings):
    tmpl = settings.template
    loc_tmpl = settings.template_location
    # values for custom
    code_val = ""
    code_line = get_line_text(d.file, d.line) if d.file else None
    if code_line is not None:
        code_val = code_line + "\n" + caret_line(d.column)
    values = {
        "file": d.file or "", "line": d.line, "column": d.column,
        "callstack": (f"[{d.file}:{d.line}]" if d.file else ""),
        "severity": d.severity, "message": d.msg, "id": d.id,
        "cwe": d.cwe if d.cwe else "", "code": code_val,
        "is_inconclusive": d.inconclusive,
    }
    out = ""
    predefined_no_notes = False
    if tmpl is None:
        out += render_default_like(d, d.severity, True, True)
    elif tmpl == "gcc":
        out += render_default_like(d, "warning", True, True)
    elif tmpl == "cppcheck1":
        if d.file:
            out += f"[{d.file}:{d.line}]: ({d.severity}) {d.msg}\n"
        else:
            out += f": ({d.severity}) {d.msg}\n"
        predefined_no_notes = True
    elif tmpl == "vs":
