def diag_xml_locations(d):
    locs = []
    primary = Loc(d.file, d.line, d.column, d.info)
    if d.file or d.line:
        locs.append(primary)
    for loc in d.callstack:
        if (loc.file, loc.line, loc.column, loc.info) == (primary.file, primary.line, primary.column, primary.info):
            continue
        if loc.file or loc.line:
            # avoid exact duplicate of primary position+info appended at end
            locs.append(loc)
    # If callstack last is the primary duplicate, it was skipped. Good.
    # Remove duplicate consecutive
    out = []
    for l in locs:
        if not out or (l.file,l.line,l.column,l.info) != (out[-1].file,out[-1].line,out[-1].column,out[-1].info):
            out.append(l)
    return out

