        if not locs and not d.symbol:
            lines.append(f'        <error {attrs}/>')
        else:
            lines.append(f'        <error {attrs}>')
            for loc in locs:
                la = f'file="{xml_escape(loc.file)}" line="{loc.line}" column="{loc.column}"'
                if loc.info:
                    la += f' info="{xml_escape(loc.info)}"'
                lines.append(f'            <location {la}/>')
            if d.symbol:
                lines.append(f'            <symbol>{xml_escape(d.symbol, attr=False)}</symbol>')
            lines.append('        </error>')
    lines.append('    </errors>')
    if version == 3:
        lines.append('')
        crit_ids = []
        for d in diags:
            if d.critical and d.id not in crit_ids: crit_ids.append(d.id)
        if crit_ids:
            lines.append(f'    <critical-errors>{xml_escape(",".join(crit_ids), attr=False)}</critical-errors>')
        else:
