                lines.append(f'            <symbol>{xml_escape(d.symbol, attr=False)}</symbol>')
            lines.append('        </error>')
    lines.append('    </errors>')
    if version == 3:
        lines.append('')
        crit_ids = []
        for d in diags:
            if d.critical and d.id not in crit_ids: crit_ids.append(d.id)
        if crit_ids:
            lines.append(f'    <critical-errors>{xml_escape(",".join(crit_ids), attr=False)}</critical-errors>')
        else:
            lines.append('    <critical-errors/>')
        aset = active_checker_set(settings, overall_lang, critical=False)
        if crit_ids:
            aset = {"CheckBufferOverrun::analyseWholeProgram","CheckClass::analyseWholeProgram","CheckNullPointer::analyseWholeProgram","CheckUninitVar::analyseWholeProgram"}
        entries = checker_template(overall_lang)
        lines.append('    <checkers-report>')
        for (name, _line, _yes) in entries:
            if name in aset:
                lines.append(f'        <checker id="{xml_escape(name)}"/>')
        lines.append('    </checkers-report>')
    lines.append('</results>')
    return "\n".join(lines) + "\n"

def render_sarif(diags, settings):
    results = []
    rules = []
    rule_ids = []
    sev_map = {"error": ("error", "9.9"), "warning": ("warning", "5.5"), "style": ("warning", "5.5"),
               "performance": ("warning", "5.5"), "portability": ("warning", "5.5"), "information": ("note", None)}
    for d in diags:
        if d.id == "checkersReport":
            continue
        level, sec = sev_map.get(d.severity, ("warning", "5.5"))
        locations = []
        locs = d.callstack if d.callstack else [Loc(d.file, d.line, d.column, d.info)]
        # sarif uses callstack order; if callstack ends with primary, it's already in order
        seen = []
        for loc in locs:
            locations.append({"physicalLocation": {"artifactLocation": {"uri": loc.file},
                "region": {"endColumn": loc.column, "endLine": loc.line, "startColumn": loc.column, "startLine": loc.line}}})
        results.append({"level": level, "locations": locations, "message": {"text": d.msg}, "ruleId": d.id})
        if d.id not in rule_ids:
            rule_ids.append(d.id)
            props = {"precision": "high", "problem.severity": level}
            if sec: props["security-severity"] = sec
            if d.cwe: props["tags"] = [f"external/cwe/cwe-{d.cwe}", "security"]
            rule = {"defaultConfiguration": {"level": level}, "fullDescription": {"text": ""},
                    "help": {"text": ""}, "id": d.id, "name": "", "properties": props, "shortDescription": {"text": ""}}
            rules.append(rule)
    obj = {"version": "2.1.0", "$schema": "https://docs.oasis-open.org/sarif/sarif/v2.1.0/errata01/os/schemas/sarif-schema-2.1.0.json",
           "runs": [{"results": results, "tool": {"driver": {"informationUri": "https://cppcheck.sourceforge.io", "name": "Cppcheck", "rules": rules, "semanticVersion": VERSION_SHORT}}}]}
    txt = json.dumps(obj, indent=2)
    txt = txt.replace("/", "\\/")
    return txt + "\n\n"

