def parse_int_value(s, optname, unsigned=False):
    t = s.strip()
    if not re.fullmatch(r"[+-]?\d+", t or ""):
        cli_fail(f"argument to '{optname}' is not valid - not an integer.")
    try:
        val = int(t)
    except Exception:
        cli_fail(f"argument to '{optname}' is not valid - not an integer.")
    # range of stoll / stoull
    if unsigned:
        if val < 0 or val > 18446744073709551615:
            cli_fail(f"argument to '{optname}' is not valid - out of range (stoull).")
    else:
        if val > 9223372036854775807 or val < -9223372036854775808:
            cli_fail(f"argument to '{optname}' is not valid - out of range (stoll).")
    return val
def check_int_limits(val, optname):
    if val > 2147483647 or val < -2147483648:
        cli_fail(f"argument to '{optname}' is not valid - out of range (limits).")
    return val

def add_define(settings, value):
    if "=" in value:
        name, val = value.split("=", 1)
        settings.defines.append((name, val))
    else:
        settings.defines.append((value, "1"))

def apply_enable(settings, value, is_enable, optname):
    if value == "":
        cli_fail(f"{optname} parameter is empty")
    parts = value.split(",")
    for p in parts:
        if p == "":
            cli_fail(f"{optname}--enable parameter is empty")
        if p not in ENABLE_NAMES:
            cli_fail(f"{optname} parameter with the unknown name '{p}'")
    for p in parts:
        if is_enable:
            if p == "all":
                settings.enabled.update(["warning","style","performance","portability","information"])
                settings.unused_function = True; settings.missing_include = True
            elif p == "style":
                settings.enabled.update(["style","warning","performance","portability"])
            elif p == "unusedFunction":
                settings.unused_function = True
            elif p == "missingInclude":
                settings.missing_include = True
            else:
                settings.enabled.add(p)
        else:
            if p == "all":
                settings.enabled.clear(); settings.unused_function = False; settings.missing_include = False
            elif p == "unusedFunction":
                settings.unused_function = False
            elif p == "missingInclude":
                settings.missing_include = False
            elif p == "style":
                settings.enabled.discard("style")
