        if not isinstance(data, list):
            raise CliError(f"cppcheck: error: compilation database is not a JSON array\ncppcheck: error: failed to load project '{path}'. An error occurred.\n")
        entries = []
        for ent in data:
            if not isinstance(ent, dict): continue
            directory = ent.get("directory") or os.getcwd()
            file_ = ent.get("file") or ""
            if not file_: continue
            cmd = ent.get("command") or ""
            args_arr = ent.get("arguments") or []
            if args_arr:
                toks_cmd = [str(x) for x in args_arr]
