            ii = 0
            while ii < len(toks_cmd):
                tk = toks_cmd[ii]
                if tk.startswith("-D") and len(tk) > 2:
                    v = tk[2:]
                    if "=" in v: nm, vv = v.split("=",1); defs.append((nm, vv))
                    else: defs.append((v, "1"))
                elif tk == "-D" and ii+1 < len(toks_cmd):
                    ii += 1; v = toks_cmd[ii]
                    if "=" in v: nm, vv = v.split("=",1); defs.append((nm, vv))
                    else: defs.append((v, "1"))
                elif tk.startswith("-I") and len(tk) > 2:
                    incs.append(tk[2:].lstrip("="))
                elif tk == "-I" and ii+1 < len(toks_cmd):
                    ii += 1; incs.append(toks_cmd[ii])
                ii += 1
            if os.path.isabs(file_):
                disp = file_; actual = file_
            else:
                actual = os.path.join(directory, file_)
                disp = actual
            entries.append(FileInput(display=disp, path=actual, defines=defs, includes=incs, language=lang))
        settings.project_entries = entries
    elif low.endswith(".cppcheck"):
        try:
            root = ET.fromstring(read_source(path))
        except Exception:
            raise CliError(f"cppcheck: error: failed to load project '{path}'. An error occurred.\n")
        dirs = []
        root_name = None
        for el in root.iter():
            if el.tag == "root" and el.get("name"): root_name = el.get("name")
            if el.tag == "dir" and el.get("name"): dirs.append(el.get("name"))
            if el.tag in ("define",) and el.get("name"):
