        settings._project_root = root_name
    elif low.endswith(".sln") or low.endswith(".vcxproj") or low.endswith(".bpr"):
        text = read_source(path)
        base = os.path.dirname(path)
        entries = []
        for m in re.finditer(r'Include="([^"]+\.(?:c|cpp|cxx|cc|h|hpp))"', text):
            rel = m.group(1).replace("\\", "/")
            actual = os.path.join(base, rel) if not os.path.isabs(rel) else rel
            entries.append(FileInput(display=actual, path=actual))
        # sln referencing vcxproj files
        if low.endswith(".sln"):
            for m in re.finditer(r'"([^"]+\.vcxproj)"', text):
