def parse_args(argv):
    s = Settings()
    events = InputEvents()
    i = 0
    def need_next(opt_display):
        nonlocal i
        if i+1 >= len(argv) or (argv[i+1].startswith("-") and argv[i+1] != "-"):
            # cppcheck treats next starting with '-' as missing for -j/-l
            cli_fail(f"argument to '{opt_display}' is missing.")
        i += 1
        return argv[i]
    while i < len(argv):
        arg = argv[i]
        if arg.startswith("--"):
            if "=" in arg:
                name, value = arg.split("=", 1); has_eq = True
            else:
                name, value, has_eq = arg, None, False
            # boolean options
            bool_opts = {
                "--check-config": "check_config", "--check-library": "check_library", "--dump": "dump",
                "--force": "force", "--inconclusive": "inconclusive", "--inline-suppr": "inline_suppr",
                "--quiet": "quiet", "--verbose": "verbose", "--xml": "xml", "--safety": "safety",
            }
            if name in bool_opts and not has_eq:
                attr = bool_opts[name]
                if attr == "xml": s.xml = True
                elif attr == "safety":
                    s.safety = True; s.enabled.add("information")
                else: setattr(s, attr, True)
                i += 1; continue
            if name in ("--fsigned-char", "--funsigned-char") and not has_eq:
                s.fsigned_char = (name == "--fsigned-char"); i += 1; continue
            if name == "--report-progress" and not has_eq:
                i += 1; continue
            if name == "--clang":
                s.clang_set = True; s.clang = value if (has_eq and value) else "clang"; i += 1; continue
            if name in ("--relative-paths", "-rp"):
                s.relative_paths_set = True
                if has_eq and value:
                    s.relative_paths.extend([x for x in value.split(";") if x != ""])
                i += 1; continue
            # value-required options: must have '='
            if not has_eq:
                cli_fail(f'unrecognized command line option: "{arg}".')
            v = value
            if name == "--enable": apply_enable(s, v, True, "--enable")
            elif name == "--disable": apply_enable(s, v, False, "--disable")
            elif name == "--std":
                if v not in STD_VALUES: cli_fail(f"unknown --std value '{v}'")
                s.std = v
            elif name == "--platform":
                if v == "": cli_fail("empty platform specified.")
                if v in PLATFORMS_BUILTIN: s.platform = v; s.platform_set = True
                elif os.path.isfile(v):
                    try:
                        r = ET.fromstring(read_source(v))
                        if r.tag != "platform": raise ValueError()
                        s.platform = v; s.platform_set = True
                    except CliError: raise
                    except Exception: cli_fail(f"unrecognized platform: '{v}'.")
                else: cli_fail(f"unrecognized platform: '{v}'.")
            elif name == "--language":
                if v not in ("c", "c++"): cli_fail(f"unknown language '{v}' enforced.")
                s.language = v
            elif name == "--check-level":
                if v not in ("reduced","normal","exhaustive"): cli_fail(f"unknown '--check-level' value '{v}'.")
                s.check_level = v
            elif name == "--output-format":
                if v not in ("text","sarif","xml","xmlv2","xmlv3"):
                    cli_fail("argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.")
                s.output_format = v; s.output_format_set = True
            elif name == "--xml-version":
                val = check_int_limits(parse_int_value(v, "--xml-version="), "--xml-version=")
                if val not in (2,3): cli_fail("'--xml-version' can only be 2 or 3.")
                s.xml_version = val; s.xml_version_set = True
            elif name == "--error-exitcode":
                s.error_exitcode = check_int_limits(parse_int_value(v, "--error-exitcode="), "--error-exitcode=")
            elif name == "--max-configs":
                val = check_int_limits(parse_int_value(v, "--max-configs="), "--max-configs=")
                if val <= 0: cli_fail("argument to '--max-configs=' must be greater than 0.")
                s.max_configs = val
            elif name == "--max-ctu-depth":
                s.max_ctu_depth = check_int_limits(parse_int_value(v, "--max-ctu-depth="), "--max-ctu-depth=")
            elif name == "--showtime":
                if v == "": cli_fail("no mode provided for --showtime")
                if v not in ("none","file","file-total","summary","top5_file","top5_summary"):
                    cli_fail(f"unrecognized --showtime mode: '{v}'. Supported modes: file, file-total, summary, top5_file, top5_summary.")
                s.showtime = None if v == "none" else v
            elif name == "--report-type":
                if v not in REPORT_TYPES: cli_fail(f"Unknown report type '{v}'")
                s.report_type = v
            elif name == "--template": s.template = v
            elif name == "--template-location": s.template_location = v
            elif name == "--suppress": s.suppressions.append(parse_suppression_spec(v))
            elif name == "--suppressions-list":
                txt = read_text_file_or_fail(v, "suppressions")
                for line in txt.splitlines():
                    line=line.strip()
                    if line: s.suppressions.append(parse_suppression_spec(line))
            elif name == "--exitcode-suppressions":
                txt = read_text_file_or_fail(v, "exitcode")
                for line in txt.splitlines():
                    line=line.strip()
                    if line: s.exitcode_suppressions.append(parse_suppression_spec(line))
            elif name == "--suppress-xml":
                if not os.path.isfile(v):
                    cli_fail(f"failed to load suppressions XML '{v}' (XML_ERROR_FILE_NOT_FOUND).")
                try:
                    root = ET.fromstring(read_source(v))
                except Exception:
                    cli_fail(f"failed to load suppressions XML '{v}' (XML_ERROR_PARSING).")
                for sup in root.iter("suppress"):
                    eid = sup.get("id"); fname = sup.get("fileName") or sup.get("file"); line = sup.get("lineNumber") or sup.get("line")
                    for ch in sup:
                        if ch.tag == "id": eid = (ch.text or "").strip()
                        elif ch.tag in ("fileName","file"): fname = (ch.text or "").strip()
                        elif ch.tag in ("lineNumber","line"): line = (ch.text or "").strip()
                    if not eid: cli_fail("Failed to add suppression. No id.")
                    try: ln = int(line) if line else None
                    except Exception: ln = None
