            elif name == "--file-list":
                if v == "-":
                    txt = sys.stdin.read()
                    files = [l for l in txt.splitlines() if l.strip() != ""]
                else:
                    txt = read_text_file_or_fail(v, "file-list")
                    files = [l.strip() for l in txt.splitlines() if l.strip() != ""]
                    # keep lines as-is except strip? filenames may contain spaces; cppcheck trims
                    files = [l.strip() for l in txt.splitlines() if l.strip() != ""]
                events.events.append(("files", files))
            elif name == "--file-filter": s.file_filters.append(v)
            elif name == "--includes-file":
                txt = read_text_file_or_fail(v, "includes")
                for line in txt.splitlines():
                    if line.strip(): s.include_paths.append(line.strip())
            elif name == "--include": s.includes.append(v)
            elif name == "--config-excludes-file":
                txt = read_text_file_or_fail(v, "config-excludes")
                # stored but unused
                s.__dict__.setdefault("config_excludes", []).extend([l.strip() for l in txt.splitlines() if l.strip()])
            elif name == "--config-exclude": s.__dict__.setdefault("config_excludes", []).append(v)
            elif name == "--library":
                if v == "": cli_fail("empty library specified.")
                s.libraries.append(v)
            elif name == "--addon": s.addons.append(v)
            elif name == "--addon-python": s.addon_python = v
            elif name == "--cppcheck-build-dir": s.cppcheck_build_dir = v
            elif name == "--output-file": s.output_file = v
            elif name == "--plist-output": s.plist_output = v
            elif name == "--checkers-report": s.checkers_report = v
            elif name == "--project": load_project_file(s, v)
            elif name == "--project-configuration": s.project_configuration = v
            elif name == "--rule":
                cli_fail("Option --rule cannot be used as Cppcheck has not been built with rules support.")
            elif name == "--rule-file":
                cli_fail("Option --rule-file cannot be used as Cppcheck has not been built with rules support.")
            else:
                cli_fail(f'unrecognized command line option: "{arg}".')
            i += 1; continue
        elif arg.startswith("-") and arg != "-":
            # short options
            if arg == "-E": s.preprocess_only = True; i += 1; continue
            if arg == "-f": s.force = True; i += 1; continue
            if arg == "-q": s.quiet = True; i += 1; continue
            if arg == "-v": s.verbose = True; i += 1; continue
            if arg in ("-rp",):
                s.relative_paths_set = True; i += 1; continue
            if arg.startswith("-rp="):
                s.relative_paths_set = True
                s.relative_paths.extend([x for x in arg[4:].split(";") if x]); i += 1; continue
            if arg == "-x" or arg.startswith("-x"):
                if arg == "-x":
                    if i+1 >= len(argv): cli_fail("no language given to '-x' option.")
                    i += 1; v = argv[i]
                else:
                    v = arg[2:].lstrip("=")
                if v not in ("c", "c++"): cli_fail(f"unknown language '{v}' enforced.")
                s.language = v; i += 1; continue
            if arg == "-j" or (arg.startswith("-j") and len(arg) > 2):
                if arg == "-j":
                    v = need_next("-j")
                else: v = arg[2:]
                val_unsigned = parse_int_value(v, "-j", unsigned=True)
                if val_unsigned > 4294967295:
                    cli_fail("argument to '-j' is not valid - out of range (limits).")
                if val_unsigned == 0: cli_fail("argument for '-j' must be greater than 0.")
                if val_unsigned > 1024: cli_fail("argument for '-j' is allowed to be 1024 at max.")
                s.jobs = val_unsigned; i += 1; continue
            if arg == "-l" or (arg.startswith("-l") and len(arg) > 2 and (len(arg) == 2 or arg[2:][0].isdigit())):
                if arg == "-l": v = need_next("-l")
                else: v = arg[2:]
                s.load = check_int_limits(parse_int_value(v, "-l"), "-l"); i += 1; continue
            if arg == "-D" or arg.startswith("-D"):
                if arg == "-D":
                    if i+1 >= len(argv): cli_fail("argument to '-D' is missing.")
                    i += 1; v = argv[i]
                else: v = arg[2:]
                if v.startswith("="): v = v[1:]
                if v: add_define(s, v)
                i += 1; continue
            if arg == "-U" or arg.startswith("-U"):
                if arg == "-U":
                    if i+1 >= len(argv): cli_fail("argument to '-U' is missing.")
                    i += 1; v = argv[i]
                else: v = arg[2:]
                if v.startswith("="): v = v[1:]
                if v: s.undefines.append(v.split("=")[0])
                i += 1; continue
            if arg == "-I" or arg.startswith("-I"):
                if arg == "-I":
                    if i+1 >= len(argv): cli_fail("argument to '-I' is missing.")
                    i += 1; v = argv[i]
                else: v = arg[2:]
                if v.startswith("="): v = v[1:]
                s.include_paths.append(v); i += 1; continue
            if arg == "-i" or (arg.startswith("-i") and len(arg) > 2):
                if arg == "-i":
                    if i+1 >= len(argv): cli_fail("argument to '-i' is missing.")
                    i += 1; v = argv[i]
                else: v = arg[2:]
                s.ignore_patterns.append(v); i += 1; continue
            cli_fail(f'unrecognized command line option: "{arg}".')
        else:
            if arg == "-":
                cli_fail('unrecognized command line option: "-".')
            events.events.append(("path", arg))
            i += 1; continue
        i += 1
    return s, events

