    if not re.fullmatch(r"[+-]?\d+", t or ""):
        cli_fail(f"argument to '{optname}' is not valid - not an integer.")
    try:
        val = int(t)
    except Exception:
        cli_fail(f"argument to '{optname}' is not valid - not an integer.")
    # range of stoll / stoull
    if unsigned:
        if val < 0 or val > 18446744073709551615:
            cli_fail(f"argument to '{optname}' is not valid - out of range (stoull).")
    else:
        if val > 9223372036854775807 or val < -9223372036854775808:
            cli_fail(f"argument to '{optname}' is not valid - out of range (stoll).")
    return val
def check_int_limits(val, optname):
    if val > 2147483647 or val < -2147483648:
        cli_fail(f"argument to '{optname}' is not valid - out of range (limits).")
    return val

def add_define(settings, value):
    if "=" in value:
        name, val = value.split("=", 1)
        settings.defines.append((name, val))
    else:
        settings.defines.append((value, "1"))

def apply_enable(settings, value, is_enable, optname):
    if value == "":
        cli_fail(f"{optname} parameter is empty")
    parts = value.split(",")
    for p in parts:
        if p == "":
            cli_fail(f"{optname}--enable parameter is empty")
        if p not in ENABLE_NAMES:
            cli_fail(f"{optname} parameter with the unknown name '{p}'")
    for p in parts:
        if is_enable:
            if p == "all":
                settings.enabled.update(["warning","style","performance","portability","information"])
                settings.unused_function = True; settings.missing_include = True
            elif p == "style":
                settings.enabled.update(["style","warning","performance","portability"])
            elif p == "unusedFunction":
                settings.unused_function = True
            elif p == "missingInclude":
                settings.missing_include = True
            else:
                settings.enabled.add(p)
        else:
            if p == "all":
                settings.enabled.clear(); settings.unused_function = False; settings.missing_include = False
            elif p == "unusedFunction":
                settings.unused_function = False
            elif p == "missingInclude":
                settings.missing_include = False
            elif p == "style":
                settings.enabled.discard("style")
            else:
                settings.enabled.discard(p)

def parse_suppression_spec(spec):
    if spec == "" or spec.split(":")[0] == "":
        cli_fail("Failed to add suppression. No id.")
    parts = spec.split(":")
    eid = parts[0]
    fname = None; line = None
    if len(parts) >= 2 and parts[1] != "":
        fname = parts[1]
    if len(parts) >= 3:
        rest = ":".join(parts[2:])
        try: line = int(rest)
        except Exception: line = None
    return (eid, fname, line)

def read_text_file_or_fail(path, kind):
    if path == "-" and kind in ("file-list","suppressions","exitcode"):
        return sys.stdin.read()
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    except Exception:
        if kind == "file-list":
            cli_fail(f"couldn't open the file: \"{path}\".")
        if kind in ("suppressions","exitcode"):
            cli_fail(f"couldn't open the file: \"{path}\".")
        if kind == "includes":
            cli_fail(f"unable to open includes file at '{path}'")
        if kind == "config-excludes":
            cli_fail(f"unable to open config excludes file at '{path}'")
        cli_fail(f"couldn't open the file: \"{path}\".")

def load_project_file(settings, path):
    settings.project = path; settings.project_set = True
    if not os.path.isfile(path):
        cli_fail(f"failed to open project '{path}'. The file does not exist.")
    low = path.lower()
    if low.endswith(".json"):
        try:
            data = json.loads(read_source(path))
        except Exception:
            data = None
        if not isinstance(data, list):
            raise CliError(f"cppcheck: error: compilation database is not a JSON array\ncppcheck: error: failed to load project '{path}'. An error occurred.\n")
        entries = []
        for ent in data:
            if not isinstance(ent, dict): continue
            directory = ent.get("directory") or os.getcwd()
            file_ = ent.get("file") or ""
            if not file_: continue
            cmd = ent.get("command") or ""
            args_arr = ent.get("arguments") or []
            if args_arr:
                toks_cmd = [str(x) for x in args_arr]
            else:
                try: toks_cmd = shlex.split(cmd)
                except Exception: toks_cmd = cmd.split()
            defs = []; incs = []; lang = None
            ii = 0
            while ii < len(toks_cmd):
                tk = toks_cmd[ii]
                if tk.startswith("-D") and len(tk) > 2:
                    v = tk[2:]
                    if "=" in v: nm, vv = v.split("=",1); defs.append((nm, vv))
                    else: defs.append((v, "1"))
                elif tk == "-D" and ii+1 < len(toks_cmd):
                    ii += 1; v = toks_cmd[ii]
                    if "=" in v: nm, vv = v.split("=",1); defs.append((nm, vv))
                    else: defs.append((v, "1"))
                elif tk.startswith("-I") and len(tk) > 2:
                    incs.append(tk[2:].lstrip("="))
                elif tk == "-I" and ii+1 < len(toks_cmd):
                    ii += 1; incs.append(toks_cmd[ii])
                ii += 1
            if os.path.isabs(file_):
                disp = file_; actual = file_
            else:
                actual = os.path.join(directory, file_)
                disp = actual
            entries.append(FileInput(display=disp, path=actual, defines=defs, includes=incs, language=lang))
        settings.project_entries = entries
    elif low.endswith(".cppcheck"):
        try:
            root = ET.fromstring(read_source(path))
        except Exception:
            raise CliError(f"cppcheck: error: failed to load project '{path}'. An error occurred.\n")
        dirs = []
        root_name = None
        for el in root.iter():
            if el.tag == "root" and el.get("name"): root_name = el.get("name")
            if el.tag == "dir" and el.get("name"): dirs.append(el.get("name"))
            if el.tag in ("define",) and el.get("name"):
                nm = el.get("name")
                # ignore
            if el.tag == "importproject":
                pass
        if not dirs and root_name: dirs = [root_name]
        settings.project_entries = []
        settings._project_dirs = dirs
        settings._project_root = root_name
    elif low.endswith(".sln") or low.endswith(".vcxproj") or low.endswith(".bpr"):
        text = read_source(path)
        base = os.path.dirname(path)
        entries = []
        for m in re.finditer(r'Include="([^"]+\.(?:c|cpp|cxx|cc|h|hpp))"', text):
            rel = m.group(1).replace("\\", "/")
            actual = os.path.join(base, rel) if not os.path.isabs(rel) else rel
            entries.append(FileInput(display=actual, path=actual))
        # sln referencing vcxproj files
        if low.endswith(".sln"):
            for m in re.finditer(r'"([^"]+\.vcxproj)"', text):
                proj = os.path.join(base, m.group(1).replace("\\","/"))
                if os.path.isfile(proj):
                    sub = Settings()
                    try:
                        load_project_file(sub, proj)
                        entries.extend(sub.project_entries or [])
                    except Exception:
                        pass
        settings.project_entries = entries
    else:
        cli_fail(f"failed to load project '{path}'. The format is unknown.")

