            if name in ("--fsigned-char", "--funsigned-char") and not has_eq:
                s.fsigned_char = (name == "--fsigned-char"); i += 1; continue
            if name == "--report-progress" and not has_eq:
                i += 1; continue
            if name == "--clang":
                s.clang_set = True; s.clang = value if (has_eq and value) else "clang"; i += 1; continue
            if name in ("--relative-paths", "-rp"):
                s.relative_paths_set = True
                if has_eq and value:
                    s.relative_paths.extend([x for x in value.split(";") if x != ""])
                i += 1; continue
            # value-required options: must have '='
            if not has_eq:
                cli_fail(f'unrecognized command line option: "{arg}".')
            v = value
            if name == "--enable": apply_enable(s, v, True, "--enable")
            elif name == "--disable": apply_enable(s, v, False, "--disable")
            elif name == "--std":
