                        r = ET.fromstring(read_source(v))
                        if r.tag != "platform": raise ValueError()
                        s.platform = v; s.platform_set = True
                    except CliError: raise
                    except Exception: cli_fail(f"unrecognized platform: '{v}'.")
                else: cli_fail(f"unrecognized platform: '{v}'.")
            elif name == "--language":
                if v not in ("c", "c++"): cli_fail(f"unknown language '{v}' enforced.")
                s.language = v
            elif name == "--check-level":
                if v not in ("reduced","normal","exhaustive"): cli_fail(f"unknown '--check-level' value '{v}'.")
                s.check_level = v
            elif name == "--output-format":
                if v not in ("text","sarif","xml","xmlv2","xmlv3"):
