def check_library_xml(actual, disp, is_std, out_warnings):
    content = read_source(actual)
    prefix = ""
    def fail(badmsg):
        lines = ""
        if prefix: lines += prefix
        lines += f"cppcheck: Failed to load library configuration file '{disp}'. {badmsg}\n"
        if is_std: lines += FILES_DIR_MSG + "\n"
