        # approximate tinyxml2 error
        if content.lstrip().startswith("<"):
            prefix = "Error=XML_ERROR_PARSING ErrorID=7 (0x7) Line number=1\n"
        else:
            prefix = "Error=XML_ERROR_PARSING_TEXT ErrorID=8 (0x8) Line number=1\n"
        fail("Bad XML")
    if root.tag != "def":
        fail(f"File is of unsupported format version '{root.tag}'")
    fmt = root.get("format")
    if fmt is not None and fmt not in ("1", "2"):
        fail(f"File is of unsupported format version '{fmt}'")
