def path_match(path, pattern):
    if not pattern: return False
    p = path.replace("\\", "/"); pat = pattern.replace("\\", "/")
    # direct / component matching for non-wildcard
    if not any(c in pat for c in "*?[]"):
        pat_n = pat.strip("/")
        if p == pat_n or p.endswith("/" + pat_n): return True
        if p.startswith(pat_n + "/"): return True
        if ("/" + pat_n + "/") in ("/" + p + "/"): return True
        if os.path.basename(p) == pat_n: return True
        return False
    # wildcard
    candidates = [p, os.path.basename(p)]
    parts = p.split("/")
    for k in range(len(parts)):
        candidates.append("/".join(parts[k:]))
    for cand in candidates:
        if fnmatch.fnmatchcase(cand, pat): return True
        # patterns like *a.c should match basename etc already; also try matching with leading */
        if fnmatch.fnmatchcase(cand, pat.lstrip("/")): return True
    return False

