    all_diags = []
    file_diags = {}
    file_funcs = {}
    analyzers_all = []
    langs = []
    critical_any = False
    crit_ids = []
    preprocess_outputs = []
    total_size = 0
    sizes = []
    for fi in files:
        try: sz = os.path.getsize(fi.path)
        except Exception: sz = 0
        sizes.append(sz); total_size += sz
    showtime_lines_template = load_resource("showtime.txt").splitlines()
    def showtime_block(mode, fi=None, final=False):
        lines = []
        if mode in ("file","top5_file"):
            use = showtime_lines_template[:5] if mode == "top5_file" else showtime_lines_template[:-1]
            lines.append("")
            lines.extend(use)
            lines.append(f"Check time: {fi.display}: 0.000s")
        elif mode in ("summary","top5_summary"):
            use = showtime_lines_template[:5] if mode == "top5_summary" else showtime_lines_template
            lines.append("")
            lines.extend(use)
            if mode == "top5_summary":
                lines.append("Overall time: 0.000s")
        elif mode == "file-total":
            lines.append(f"Check time: {fi.display}: 0.000s")
