            diags, analyzers, lng, pp_res = process_one_file(fi, settings, None)
            if pp_res is not None:
                preprocess_outputs.append("\n".join(pp_res.e_lines) + "\n")
            file_diags[fi.display] = []
            continue
        if not settings.quiet:
            out_checking(f"Checking {fi.display} ...\n")
            if settings.verbose:
                defs_txt = ";".join(f"{n}={v}" for (n,v) in (list(settings.defines) + list(fi.defines)))
                undef_txt = "" if not settings.undefines else " " + "; ".join(settings.undefines)
                inc_txt = ""
                if settings.include_paths:
                    inc_txt = "".join(f" -I{x.rstrip('/')}/" for x in settings.include_paths)
                plat = settings.platform
                out_checking(f"Defines:{defs_txt}\nUndefines:{undef_txt}\nIncludes:{inc_txt}\nPlatform:{plat}\n")
        # config lines need to be emitted; process_one_file recomputes configs, so emit here by replicating config labels
        config_labels = []
        merged_defs = list(settings.defines) + list(fi.defines)
        if not settings.check_config:
            if merged_defs:
                config_labels = [";".join(f"{n}={v}" for (n,v) in merged_defs)]
            else:
                symbols = discover_config_symbols(fi.display, fi.path, settings, lang)
                if symbols:
                    cfg_list = symbols if settings.force else symbols
                    # number of configs incl empty limited
                    max_auto = max(0, settings.max_configs - 1)
                    if not settings.force and len(cfg_list) > max_auto: cfg_list = cfg_list[:max_auto]
                    config_labels = [f"{sym}={sym}" for sym in cfg_list]
        diags, analyzers, lng, _ = process_one_file(fi, settings, None)
        langs[-1] = lng
        analyzers_all.extend([(fi, a) for a in analyzers])
        for lbl in config_labels:
            if not settings.quiet:
                out_checking(f"Checking {fi.display}: {lbl}...\n")
        if settings.clang_set:
            # attempt clang execution per file
            clang_exec = settings.clang or "clang"
            xl = "c++" if lng == "cpp" else "c"
            cmd = f"{clang_exec} -fsyntax-only -Xclang -ast-dump -fno-color-diagnostics -x {xl} {fi.display} 2>&1"
            try:
                p = subprocess.run(cmd, shell=True, capture_output=True, text=True)
                outp = (p.stdout or "") + (p.stderr or "")
                if p.returncode != 0:
                    sys.stderr.write(f"Failed to execute '{cmd}' - (exitcode: {p.returncode} / output: {outp})\n")
            except Exception as e:
                sys.stderr.write(f"Failed to execute '{cmd}' - (exitcode: 127 / output: sh: 1: {clang_exec}: not found\n)\n")
            diags = []
        # dump
        if settings.dump and analyzers:
            write_dump(fi, analyzers[0].toks if analyzers else [], lng, settings)
        elif settings.dump:
            write_dump(fi, [], lng, settings)
        # sort diagnostics for this file by rank (stable)
        diags_sorted = sorted(diags, key=lambda d: diag_rank(d))
        file_diags[fi.display] = diags_sorted
        for d in diags_sorted:
            if d.critical:
                critical_any = True
                if d.id not in crit_ids: crit_ids.append(d.id)
        all_diags.extend(diags_sorted)
        func_names = []
        for a in analyzers:
            for fn in a.functions: func_names.append(fn.name)
        file_funcs[fi.display] = func_names
        cum += sizes[idx]
        if not settings.quiet and len(files) > 1:
            pct = int(cum * 100 / total_size) if total_size > 0 else 100
            out_progress(f"{idx+1}/{len(files)} files checked {pct}% done\n")
        if settings.showtime in ("file","file-total","top5_file"):
            out_other(showtime_block(settings.showtime, fi))
    if settings.preprocess_only:
        sys.stdout.write("".join(preprocess_outputs))
