    if settings.inline_suppr:
        kept = []
        matched_keys = set()
        for d in filtered:
            supps = inline_by_file.get(d.file, [])
            matched = False
            for si, sup in enumerate(supps):
                if (sup["id"] == "*" or sup["id"] == d.id) and sup["target"] == d.line:
                    matched = True; matched_keys.add((d.file, si)); break
            if not matched: kept.append(d)
        # unmatched
        if "information" in settings.enabled:
            for fi in files:
                for si, sup in enumerate(inline_by_file.get(fi.display, [])):
                    if (fi.display, si) not in matched_keys:
                        d = make_diag("unmatchedSuppression", f"Unmatched suppression: {sup['id']}",
                                      Loc(fi.display, sup["target"], 0), gate="information", file0=False)
                        if not any(suppression_matches(sp, d) for sp in settings.suppressions):
                            unmatched.append(d)
        filtered = kept + unmatched
    # relative paths
    if settings.relative_paths_set and settings.relative_paths:
        for d in filtered:
            for base in settings.relative_paths:
                b = base.rstrip("/")
                if b and d.file.startswith(b + "/"):
                    old = d.file
                    d.file = d.file[len(b)+1:]
                    if old in FILE_LINES and d.file not in FILE_LINES:
                        FILE_LINES[d.file] = FILE_LINES[old]
                    break
                if b and d.file == b:
                    break
            for loc in d.callstack:
                for base in settings.relative_paths:
                    b = base.rstrip("/")
                    if b and loc.file.startswith(b + "/"):
                        old = loc.file; loc.file = loc.file[len(b)+1:]
                        if old in FILE_LINES and loc.file not in FILE_LINES: FILE_LINES[loc.file] = FILE_LINES[old]
                        break
    # checkers report diagnostic
    if settings.showtime in ("summary","top5_summary"):
        out_other(showtime_block(settings.showtime, None, final=True))
    # stdout (progress) output ordering for -j
    if settings.jobs > 1 and len(files) > 1:
        for kind in ("checking","progress","other"):
            for (k, txt) in stdout_chunks:
                if k == kind: sys.stdout.write(txt)
    else:
        for (k, txt) in stdout_chunks:
            sys.stdout.write(txt)
    # checkers report file
    if settings.checkers_report:
        write_checkers_report(settings, overall_lang, critical_any, crit_ids)
    # checkers diag (information)
    checkers_diag = None
    if "information" in settings.enabled:
        if critical_any:
            msg = "Active checkers: There was critical errors"
            if not settings.checkers_report and not (settings.output_format == "xmlv3" or settings.xml_version == 3 and (settings.xml or settings.output_format)):
                msg += " (use --checkers-report=<filename> to see details)"
            checkers_diag = make_diag("checkersReport", msg, Loc("",0,0), gate="information", file0=False)
        else:
            cnt = checker_count(settings, overall_lang, False)
            msg = f"Active checkers: {cnt}/186"
            is_xmlv3 = (settings.output_format == "xmlv3") or (settings.xml_version == 3 and (settings.xml or settings.output_format_set))
            if not settings.checkers_report and not is_xmlv3:
                msg += " (use --checkers-report=<filename> to see details)"
            checkers_diag = make_diag("checkersReport", msg, Loc("",0,0), gate="information", file0=False)
        if checkers_diag is not None:
            if not any(suppression_matches(sp, checkers_diag) for sp in settings.suppressions):
                filtered.append(checkers_diag)
    render_and_output(settings, filtered, overall_lang, critical_any)
    if settings.cppcheck_build_dir:
        # rebuild file_diags after filtering per file: approximate with filtered grouped
        fd = {}
        for d in filtered:
            fd.setdefault(d.file, []).append(d)
        write_build_dir(settings, files, fd, file_funcs, overall_lang, critical_any)
    if settings.plist_output:
        fd = {}
        for d in filtered:
            if d.file: fd.setdefault(d.file, []).append(d)
        write_plist(settings, files, fd)
    # exit code
    exit_diags = []
    for d in filtered:
        if d.id == "checkersReport": continue
        if any(suppression_matches(sp, d) for sp in settings.exitcode_suppressions): continue
        exit_diags.append(d)
    if exit_diags and settings.error_exitcode != 0:
        return settings.error_exitcode
    return 0

def whole_program_functions(analyzers_all, settings):
    unused = []; static = []
    defs = []
    # call sites: called name -> set of caller identifiers (function display+index) and member calls
    # Analyzer.collect_calls filled called_names globally per TU, but for recursion we approximate:
    for (fi, a) in analyzers_all:
        for f in a.functions:
            defs.append((fi, a, f))
    # build global called set excluding a function's own recursive calls:
    # counts occurrences: we recompute by scanning analyzers: if a function name call appears only inside its own body, ignore.
    for (fi, a, f) in defs:
        if f.name == "main": continue
        if getattr(f, "has_extern_decl", False): continue
        used = False
        if f.is_member:
            if f.name in a.member_called: used = True
            # also calls in other analyzers
            if any(f.name in other.member_called for (_fi, other) in analyzers_all if other is not a): used = True
            # direct unqualified calls from other functions in same class
            if f.name in a.called_names: used = True
        else:
            # count call sites outside this function body
            for (_fi2, a2) in analyzers_all:
                # tokens of a2: any call token (name followed by '(') outside f's token range (when same analyzer)
                for idx, tok in enumerate(a2.toks):
                    if tok.kind == "id" and tok.text == f.name and idx+1 < len(a2.toks) and a2.toks[idx+1].text == "(":
                        if a2 is a and f.body_start <= idx <= f.body_end:
                            continue
                        if any(ff.name_index == idx for ff in a2.functions):
                            continue
                        if idx > 0 and a2.toks[idx-1].text in (".", "->"):
                            continue
                        used = True; break
                if used: break
            # function referenced as value (address) outside body
            if not used and f.name in a.called_names:
                # if called_names came only from definitions/decls, still might be False; use token search above already covered calls
                pass
        lang = determine_language(fi, settings)
        if not used:
            loc = Loc(f.name_token.file, f.name_token.line, f.name_token.column)
            if f.is_member:
                dispname = f.name
            else:
                dispname = f.name
            d = make_diag("unusedFunction", f"The function '{dispname}' is never used.", loc, severity="style",
                          gate="unusedFunction", file0=False, symbol=dispname)
            unused.append(d)
        elif not f.is_member and lang == "c" and not f.is_static:
            loc = Loc(f.name_token.file, f.name_token.line, f.name_token.column)
            d = make_diag("staticFunction", f"The function '{f.name}' should have static linkage since it is not used outside of its translation unit.", loc,
                          severity="style", gate="unusedFunction", file0=False, symbol=f.name)
            static.append(d)
    return unused, static

def render_and_output(settings, diags, overall_lang, critical):
    fmt = settings.output_format
    is_sarif = fmt == "sarif"
    is_xml = settings.xml or (fmt in ("xml","xmlv2","xmlv3"))
    version = settings.xml_version
    if fmt == "xmlv3": version = 3
    if fmt == "xmlv2": version = 2
    if fmt == "xml": version = settings.xml_version if settings.xml_version_set else 2
    out_text = ""
    if is_sarif:
        out_text = render_sarif(diags, settings)
    elif is_xml:
        out_text = render_xml(diags, version, settings, overall_lang, critical)
    else:
        parts = []
        for d in diags:
            parts.append(render_text_diag(d, settings))
        out_text = "".join(parts)
    if settings.output_file is not None:
        if settings.output_file == "":
            return
        try:
            with open(settings.output_file, "w", encoding="utf-8") as f:
                f.write(out_text)
        except Exception:
            pass
    else:
        sys.stderr.write(out_text)

if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(0)
