import subprocess,os,glob,re,collections
from concurrent.futures import ThreadPoolExecutor
ORIG="/tmp/orig/executable"; NEW="/workspace/executable"
def run(exe,args,cwd):
    r=subprocess.run([exe]+args,capture_output=True,text=True,cwd=cwd,timeout=20); return r.stdout,r.stderr
files=[]
for d in ["/tmp/s2","/tmp/s3","/tmp/orig_test","/tmp/samples","/tmp/fmt"]:
    for p in sorted(glob.glob(d+"/*.c")+glob.glob(d+"/*.cpp")): files.append(p)
def job(p):
    d=os.path.dirname(p); n=os.path.basename(p)
    a=run(ORIG,["--xml","--enable=all",n],d); b=run(NEW,["--xml","--enable=all",n],d)
    return (n,d,a,b)
with ThreadPoolExecutor(max_workers=12) as ex: res=list(ex.map(job,files))
pat=collections.Counter(); exmap={}
for n,d,a,b in res:
    if a==b: continue
    # compare error elements
    def errs(x): return re.findall(r"<error [^>]*>",x)
    ea,eb=errs(a[1]),errs(b[1])
    key=None
    if len(ea)!=len(eb): key=f"errorcount {len(ea)}->{len(eb)}"
    else:
        for x,y in zip(ea,eb):
            if x!=y:
                # attribute diffs names
                def attrs(s): return dict(re.findall(r'(\w+)="([^"]*)"',s))
                ax,ay=attrs(x),attrs(y); diffs=[k for k in set(ax)|set(ay) if ax.get(k)!=ay.get(k)]
                key="attrs:" + ",".join(sorted(diffs)); break
        if key is None:
            # location diffs
            la=re.findall(r"<location [^>]*>",a[1]); lb=re.findall(r"<location [^>]*>",b[1])
            if la!=lb: key="locations"
            else: key="other"
    pat[key]+=1; exmap.setdefault(key,(n,d,a,b))
print("total xml fails", sum(pat.values()), "of", len(res))
for k,c in pat.most_common(30):
