"""@dataclass
class CfgPart:
    label: str = ""
    defines: list = field(default_factory=list)
    undefines: list = field(default_factory=list)

def _split_top_expr(expr, op):
    parts=[]; cur=""; depth=0; i=0
    while i < len(expr):
        if expr[i]=="(": depth+=1
        elif expr[i]==")": depth-=1
        if depth==0 and expr.startswith(op, i):
            parts.append(cur); cur=""; i+=len(op); continue
        cur+=expr[i]; i+=1
    parts.append(cur)
    return [x.strip() for x in parts]

def _strip_parens(e):
    e=e.strip()
    while e.startswith("(") and e.endswith(")"):
        # check outer parens match
        depth=0; ok=True
        for i,ch in enumerate(e):
            if ch=="(": depth+=1
            elif ch==")":
                depth-=1
                if depth==0 and i < len(e)-1: ok=False; break
        if not ok or depth!=0: break
        e=e[1:-1].strip()
    return e

def _atom_config(atom, known):
    a=_strip_parens(atom)
    m=re.fullmatch(r"defined\\s*\\(?\\s*([A-Za-z_]\\w*)\\s*\\)?", a)
    if m:
        name=m.group(1)
        if name in known: return None
        return CfgPart(label=f"{name}={name}", defines=[(name,name)])
    m=re.fullmatch(r"!\\s*defined\\s*\\(?\\s*([A-Za-z_]\\w*)\\s*\\)?", a)
    if m:
        name=m.group(1)
        if name in known: return None
        return CfgPart(label=f"{name}", undefines=[name])
    m=re.fullmatch(r"!\\s*([A-Za-z_]\\w*)", a)
    if m:
        name=m.group(1)
        if name in known: return None
        return CfgPart(label=f"{name}", undefines=[name])
    m=re.fullmatch(r"([A-Za-z_]\\w*)\\s*(==|!=|<=|>=|<|>)\\s*(-?\\d+|[A-Za-z_]\\w*|'[^']*')", a)
    if m:
        name,op,val=m.group(1),m.group(2),m.group(3)
        if name in known: return None
        chosen=val
        if val.lstrip("-").isdigit():
            iv=int(val)
            chosen=str({"==":iv,"!=":iv+1,"<":iv-1,">":iv+1,"<=":iv,">=":iv}[op])
        return CfgPart(label=f"{name}={chosen}", defines=[(name,chosen)])
    m=re.fullmatch(r"(-?\\d+)\\s*(==|!=|<=|>=|<|>)\\s*([A-Za-z_]\\w*)", a)
    if m:
        val,op,name=m.group(1),m.group(2),m.group(3)
        if name in known: return None
        iv=int(val); chosen=str({"==":iv,"!=":iv+1,">":iv-1,"<":iv+1,">=":iv,"<=":iv}[op])
        return CfgPart(label=f"{name}={chosen}", defines=[(name,chosen)])
    m=re.fullmatch(r"([A-Za-z_]\\w*)", a)
    if m:
        name=m.group(1)
        if name in known or name in ("true","false"): return None
        return CfgPart(label=f"{name}", defines=[(name,"1")])
