    parts=[]
    for mm in re.finditer(r"defined\\s*\\(?\\s*([A-Za-z_]\\w*)", a):
        name=mm.group(1)
        if name not in known: parts.append(CfgPart(label=f"{name}={name}", defines=[(name,name)]))
    if parts:
