        lab=";".join(x.label for x in parts); defs=[]
        for x in parts: defs.extend(x.defines)
        return CfgPart(label=lab, defines=defs)
    return None

def _condition_configs(kind, expr, known):
    if kind=="ifdef":
        name=expr.strip()
        if not re.fullmatch(r"[A-Za-z_]\\w*", name or "") or name in known: return []
        return [CfgPart(label=f"{name}={name}", defines=[(name,name)])]
    if kind=="ifndef":
        return []
    if kind in ("if","elif"):
        e=(expr or "").strip()
        if not e: return []
        ors=_split_top_expr(e, "||")
        if len(ors)>1:
            out=[]
            for side in ors:
                out.extend(_condition_configs("if", side, known))
            return out
        ands=_split_top_expr(e, "&&")
        if len(ands)>1:
            cfgs=[]
            for side in ands:
                c=_atom_config(side, known)
                if c is None:
                    # an atom that is a nested condition
                    sub=_condition_configs("if", side, known)
                    if sub: c=sub[0]
