def discover_configs(display, path, settings, language):
    text=read_source(path)
    cleaned=clean_source(text)
    defined_in_file=set()
    for line in cleaned.splitlines():
        m=re.match(r"\\s*#\\s*define\\s+([A-Za-z_]\\w*)", line)
        if m: defined_in_file.add(m.group(1))
    known=set(defined_in_file) | {n for (n,v) in settings.defines} | set(settings.undefines) | {"__cplusplus","__STDC__","__STDC_VERSION__","__STDC_HOSTED__"}
    configs=[]; seen=set()
