        if kind in ("ifdef","ifndef","if"):
            frame={"kind":kind,"rest":rest,"branches":[(kind,rest)]}
            stack.append(frame)
            for c in _condition_configs(kind, rest, known): add(c)
        elif kind=="elif":
            if stack: stack[-1]["branches"].append((kind,rest))
            for c in _condition_configs("if", rest, known): add(c)
        elif kind=="else":
            if stack:
                fr=stack[-1]; sk,sr=fr["kind"],fr["rest"]
                if sk=="ifndef":
                    name=sr.strip()
                    if re.fullmatch(r"[A-Za-z_]\\w*", name or "") and name not in known:
                        add(CfgPart(label=f"{name}", defines=[(name,"1")]))
