                    mm=re.fullmatch(r"!\\s*defined\\s*\\(?\\s*([A-Za-z_]\\w*)\\s*\\)?", (sr or "").strip())
                    if mm and mm.group(1) not in known:
                        nm=mm.group(1); add(CfgPart(label=f"{nm}", defines=[(nm,"1")]))
        elif kind=="endif":
            if stack: stack.pop()
    result=[CfgPart(label="", defines=[], undefines=[])]
    result.extend(configs)
    return result

def discover_config_symbols(display, path, settings, language):""")

