            prm=params[0]
            words=prm.base_words()
            if words and words[-1]==cname and (prm.is_ref or prm.pointer): continue
            # display names (instantiations if this is a template)
            ci=next((c for c in self.classes if c.name==cname), None)
            displays=[]
            if ci is not None:
                usages=[]
                for i,tok in enumerate(self.toks):
