            for disp in displays:
                loc=Loc(ntok.file, ntok.line, ntok.column)
                msg=f"Class '{disp}' has a constructor with 1 argument that is not explicit."
                self.diags.append(make_diag("noExplicitConstructor", msg, loc, severity="style", symbol=disp))

    def check_no_constructors(self):
        self.check_no_explicit_constructors()
        for ci in self.classes:""")
